#!/bin/bash
set -eo pipefail

# Parse flags
BENCHMARK_MODE=false
for arg in "$@"; do
    case "$arg" in
        --benchmark) BENCHMARK_MODE=true ;;
    esac
done

# Cloud-Linux dev envs set CONDUCTOR_* via .cloud-env (generated by
# scripts/cloud-build.sh during Cord's build phase). When .cloud-env exists,
# it is authoritative — always source it so the cloud-generated workspace
# name cannot be overridden by stale env vars or command-line params.
SCRIPT_SOURCE="${BASH_SOURCE[0]:-$0}"
SCRIPT_DIR="$(cd "$(dirname "$SCRIPT_SOURCE")" && pwd)"
if [ -f "$SCRIPT_DIR/../.cloud-env" ]; then
    . "$SCRIPT_DIR/../.cloud-env"
elif [ -z "${CONDUCTOR_PORT:-}" ]; then
    echo '❌ CONDUCTOR_PORT not set. Run via Conductor, or run scripts/cloud-build.sh first on cloud envs.'
    exit 1
fi

. "$SCRIPT_DIR/lib/workspace-env.sh"
normalize_conductor_workspace_env
. "$SCRIPT_DIR/lib/run-process-cleanup.sh"
. "$SCRIPT_DIR/lib/ngrok-tunnel.sh"
. "$SCRIPT_DIR/lib/run-context.sh"
. "$SCRIPT_DIR/lib/run-service-readiness.sh"
. "$SCRIPT_DIR/lib/seed-cache.sh"
. "$SCRIPT_DIR/lib/fast-mode-cache-schema.sh"

RUN_CONTEXT_DIR="$(normalize_run_context_dir "$PWD" "${BENCHMARK_CONTEXT_DIR:-.context}")"
BENCHMARK_ISOLATED_RUN="${BENCHMARK_ISOLATED_RUN:-false}"

# Export both benchmark-mode signals so child services (backend + worker) actually
# see them. Backend code keys benchmark-only behavior off these (purchase KYC
# simulation, the RLS-free agent preview, and the AgentCard mint cutoff's
# force-enable of real minting). `--benchmark` sets BENCHMARK_MODE locally; without
# this export it never reached the backend, so those checks silently read an unset
# var — e.g. a `run.sh --benchmark` lifecycle stack would hand the agent the static
# Rose Agent Card instead of minting a real AgentCard. The isolated `run-bench`
# path already exports BENCHMARK_ISOLATED_RUN; re-exporting here is idempotent.
export BENCHMARK_MODE BENCHMARK_ISOLATED_RUN

# mac-app is Electron + requires nvm/Node 20.10.0; only runs on macOS.
IS_MAC=false
[ "$(uname)" = "Darwin" ] && IS_MAC=true

# Assign ports from a base port. Uses offsets 0-6 (5 services + 1 DB + WMH).
# Research was retired post-rose-migration so no research ports are reserved.
# +6 is the World Model Harness serving port (benchmark/simulate only).
assign_ports() {
    local base=$1
    export BACKEND_PORT=$base
    export FRONTEND_PORT=$((base + 1))
    export HEALTH_PORT=$((base + 2))
    export MAC_APP_PORT=$((base + 3))
    export SDK_METRICS_PORT=$((base + 4))
    export LOCAL_DB_PORT=$((base + 5))
    export WMH_PORT=$((base + 6))
    export NGROK_WEB_PORT=$((base + 9))
    export BACKEND_API_URL=http://localhost:$BACKEND_PORT
    export VITE_BACKEND_API_URL=http://localhost:$BACKEND_PORT
    export BACKEND_URL=http://localhost:$BACKEND_PORT
    export ALLOWED_ORIGINS=http://localhost:$FRONTEND_PORT,http://localhost:$MAC_APP_PORT
}

docker_ps_ports_quick() {
    local tmp pid status
    tmp=$(mktemp)
    docker ps --format "$1" >"$tmp" 2>/dev/null &
    pid=$!
    # Docker Desktop can take more than one second to answer while other
    # workspaces are active. Falling back to the shared system database in that
    # case defeats per-workspace isolation and can expose a concurrently changed
    # schema, so allow a bounded five-second health probe.
    for _ in $(seq 1 25); do
        if ! kill -0 "$pid" 2>/dev/null; then
            status=0
            wait "$pid" || status=$?
            cat "$tmp"
            rm -f "$tmp"
            return $status
        fi
        sleep 0.2
    done
    kill -9 "$pid" 2>/dev/null || true
    wait "$pid" 2>/dev/null || true
    rm -f "$tmp"
    return 1
}

docker_info_quick() {
    local pid status
    docker info >/dev/null 2>&1 &
    pid=$!
    for _ in 1 2 3 4 5; do
        if ! kill -0 "$pid" 2>/dev/null; then
            status=0
            wait "$pid" || status=$?
            return $status
        fi
        sleep 0.2
    done
    kill -9 "$pid" 2>/dev/null || true
    wait "$pid" 2>/dev/null || true
    return 1
}

docker_available_for_workspace_db() {
    local db_container=$1
    docker_info_quick && return 0
    # /deploy pre-starts the worktree-owned DB. A busy Docker Desktop can make
    # the broad daemon probe miss its startup budget even while this known
    # container is available; preserve isolation instead of falling through to
    # the shared system Postgres in that case.
    docker_ps_ports_quick '{{.Names}}' | grep -Fxq "$db_container"
}

# Check cwd first because many service command lines are just "node" or
# "python3" and do not include the worktree path.
process_belongs_to_this_worktree() {
    local pid=$1
    local cwd cmd
    cwd=$(lsof -a -p "$pid" -d cwd -Fn 2>/dev/null | sed -n 's/^n//p' | head -1) || true
    if [ "$cwd" = "$PWD" ] || [[ "$cwd" == "$PWD"/* ]]; then
        return 0
    fi
    cmd=$(ps -p "$pid" -o command= 2>/dev/null) || true
    echo "$cmd" | grep -Fq "$PWD"
}

# Check if a port requires moving this workspace to a different range.
# Current-worktree processes are handled later as stale/running services; any
# other listener should trigger reassignment before services or Postgres start.
#
# Only LISTENING sockets are considered: a listener bind fails (EADDRINUSE) solely
# because another LISTENER holds the port. An outbound ESTABLISHED connection that
# merely borrowed this number as its ephemeral local port (e.g. a concurrent
# workspace's `flyctl proxy` streaming to Fly) does NOT block our bind, so it must
# not be mistaken for an occupant — otherwise unlucky ephemeral-port collisions
# across sibling workspaces spuriously fail strict-Conductor-port startup.
port_requires_reassign() {
    local port=$1
    local pids
    pids=$(lsof -nP -tiTCP:"$port" -sTCP:LISTEN 2>/dev/null) || true
    for pid in $pids; do
        local cmd
        cmd=$(ps -p "$pid" -o command= 2>/dev/null) || true
        # Docker daemon is a single process for all containers — check containers separately below
        echo "$cmd" | grep -qi docker && continue
        if ! process_belongs_to_this_worktree "$pid"; then
            return 0  # another process already owns this port
        fi
    done

    # Check if a Docker container from another workspace maps to this port.
    local docker_ports name ports
    docker_ports=$(docker_ps_ports_quick '{{.Names}}\t{{.Ports}}' | grep ":${port}->" || true)
    while IFS=$'\t' read -r name ports; do
        [ -z "$name" ] && continue
        if [ -n "${CONDUCTOR_WORKSPACE_NAME:-}" ] && echo "$name" | grep -Fq "$CONDUCTOR_WORKSPACE_NAME"; then
            continue
        fi
        return 0
    done <<< "$docker_ports"

    return 1
}

port_is_free_for_candidate_range() {
    local port=$1
    if lsof -nP -tiTCP:"$port" -sTCP:LISTEN >/dev/null 2>&1; then
        return 1
    fi
    if docker_ps_ports_quick '{{.Ports}}' | grep -q ":${port}->"; then
        return 1
    fi
    return 0
}

port_range_can_reassign() {
    if [ "${RUN_SH_STRICT_CONDUCTOR_PORT:-0}" = "1" ] || { $BENCHMARK_MODE && [ "${BENCHMARK_BUNDLED_FRONTEND:-false}" = "true" ]; }; then
        echo "❌ Port range $CONDUCTOR_PORT is occupied; strict Conductor port mode forbids reassignment." >&2
        return 1
    fi
    return 0
}

resolve_frontend_dist_dir() {
    local workspace_root=$1
    local isolated_run=$2
    local benchmark_run_id=${3:-}
    local frontend_port=${4:-}
    local dist_key
    if [ "$isolated_run" = "true" ]; then
        [ -n "$benchmark_run_id" ] || {
            echo "❌ BENCHMARK_RUN_ID is required for an isolated bundled frontend." >&2
            return 1
        }
        dist_key=$(printf '%s' "$benchmark_run_id" | tr -c '[:alnum:]_.-' '_')
    else
        [ -n "$frontend_port" ] || {
            echo "❌ FRONTEND_PORT is required for a shared bundled frontend." >&2
            return 1
        }
        dist_key="shared_${frontend_port}"
    fi
    printf '%s/.context/frontend-builds/%s\n' "${workspace_root%/}" "$dist_key"
}

if [ "${RUN_SH_SOURCE_ONLY:-false}" = "true" ]; then
    return 0 2>/dev/null || exit 0
fi

# Try the Conductor-assigned port first
assign_ports "$CONDUCTOR_PORT"

# If any port in our range is held by another process, find a safe range.
# WMH only binds WMH_PORT when it will actually be served (mirrors
# should_serve_world_model, which is defined later): a run that skips the World
# Model Harness never touches WMH_PORT, so an unrelated process occupying it
# (e.g. Spotify's local port) must not block the strict Conductor port range.
PORTS_TO_CHECK="$BACKEND_PORT $FRONTEND_PORT $HEALTH_PORT $MAC_APP_PORT $SDK_METRICS_PORT $LOCAL_DB_PORT $NGROK_WEB_PORT"
if [ "${ENVIRONMENT:-}" != "production" ] && [ "${BENCHMARK_SKIP_WMH_BUILD:-}" != "1" ]; then
    PORTS_TO_CHECK="$PORTS_TO_CHECK $WMH_PORT"
fi
COLLISION=false
for port in $PORTS_TO_CHECK; do
    if port_requires_reassign "$port"; then
        COLLISION=true
        break
    fi
done

if $COLLISION; then
    if ! port_range_can_reassign; then
        exit 1
    fi
    echo "⚠️  Port range $CONDUCTOR_PORT is already occupied — scanning for free range..."
    # Scan upward in steps of 20 from the assigned port
    CANDIDATE=$((CONDUCTOR_PORT + 20))
    FOUND=false
    while [ $CANDIDATE -lt 65500 ]; do
        RANGE_FREE=true
        for offset in 0 1 2 3 4 5 6 9; do
            p=$((CANDIDATE + offset))
            if ! port_is_free_for_candidate_range "$p"; then
                RANGE_FREE=false
                break
            fi
        done
        if $RANGE_FREE; then
            FOUND=true
            break
        fi
        CANDIDATE=$((CANDIDATE + 20))
    done
    if ! $FOUND; then
        echo "❌ Could not find a free port range. All ranges 55000-65500 occupied."
        exit 1
    fi
    assign_ports "$CANDIDATE"
    echo "✅ Reassigned to port range $CANDIDATE"
fi

IS_CLOUD=false
[ -f "$SCRIPT_DIR/../.cloud-env" ] && IS_CLOUD=true

default_benchmark_worker_processes() {
    local cpus
    cpus=1
    if command -v sysctl >/dev/null 2>&1; then
        cpus=$(sysctl -n hw.logicalcpu 2>/dev/null || echo 1)
    elif command -v nproc >/dev/null 2>&1; then
        cpus=$(nproc 2>/dev/null || echo 1)
    fi
    case "$cpus" in
        ''|*[!0-9]*) cpus=1 ;;
    esac
    if [ "$cpus" -le 2 ]; then
        echo 1
    elif [ "$cpus" -gt 14 ]; then
        echo 12
    else
        echo $((cpus - 2))
    fi
}

if ! $IS_CLOUD; then
    if $BENCHMARK_MODE; then
        export WORKER_PROCESSES="${WORKER_PROCESSES:-${BENCHMARK_AGENT_WORKERS:-$(default_benchmark_worker_processes)}}"
        export MAX_CONCURRENT_ACTIVITIES="${MAX_CONCURRENT_ACTIVITIES:-16}"
        export MAX_CONCURRENT_ACTIVITY_TASK_POLLERS="${MAX_CONCURRENT_ACTIVITY_TASK_POLLERS:-16}"
        export MAX_CONCURRENT_WORKFLOWS="${MAX_CONCURRENT_WORKFLOWS:-32}"
        export MAX_CACHED_WORKFLOWS="${MAX_CACHED_WORKFLOWS:-64}"
        export MAX_CONCURRENT_WORKFLOW_TASK_POLLERS="${MAX_CONCURRENT_WORKFLOW_TASK_POLLERS:-8}"
        export NONSTICKY_TO_STICKY_POLL_RATIO="${NONSTICKY_TO_STICKY_POLL_RATIO:-0.5}"
    else
        export MAX_CONCURRENT_ACTIVITIES="${MAX_CONCURRENT_ACTIVITIES:-500}"
        export MAX_CONCURRENT_ACTIVITY_TASK_POLLERS="${MAX_CONCURRENT_ACTIVITY_TASK_POLLERS:-80}"
    fi
fi

export NODE_ENV="${NODE_ENV:-development}"
export TEMPORAL_TASK_QUEUE
TEMPORAL_TASK_QUEUE="$(resolve_temporal_task_queue "$CONDUCTOR_WORKSPACE_NAME")"
echo "🔌 Ports: backend=$BACKEND_PORT frontend=$FRONTEND_PORT health=$HEALTH_PORT mac-app=$MAC_APP_PORT metrics=$SDK_METRICS_PORT db=$LOCAL_DB_PORT wmh=$WMH_PORT ngrok_api=$NGROK_WEB_PORT queue=$TEMPORAL_TASK_QUEUE benchmark_mode=$BENCHMARK_MODE worker_processes=${WORKER_PROCESSES:-8} workflow_max_slots=${MAX_CONCURRENT_WORKFLOWS:-50} workflow_pollers=${MAX_CONCURRENT_WORKFLOW_TASK_POLLERS:-8} nonsticky_to_sticky=${NONSTICKY_TO_STICKY_POLL_RATIO:-0.5} activity_max_slots=${MAX_CONCURRENT_ACTIVITIES:-100} activity_pollers=${MAX_CONCURRENT_ACTIVITY_TASK_POLLERS:-8}"

run_kill_stale_same_task_queue_workers "$PWD" "$TEMPORAL_TASK_QUEUE" "$BACKEND_API_URL" "$$"

is_current_process_family() {
    local pid=$1
    while [ -n "$pid" ] && [ "$pid" != "0" ]; do
        [ "$pid" = "$$" ] && return 0
        pid=$(ps -p "$pid" -o ppid= 2>/dev/null | tr -d ' ') || return 1
    done
    return 1
}

process_cwd_in_this_worktree() {
    local pid=$1
    local cwd
    cwd=$(lsof -a -p "$pid" -d cwd -Fn 2>/dev/null | sed -n 's/^n//p' | head -1) || true
    case "$cwd" in
        "$PWD"|"$PWD"/*) return 0 ;;
    esac
    return 1
}

kill_stale_tree() {
    local pid=$1
    for child in $(pgrep -P "$pid" 2>/dev/null); do
        kill_stale_tree "$child"
    done
    kill "$pid" 2>/dev/null || true
}

kill_stale_same_worktree_benchmark_stack() {
    $BENCHMARK_MODE || return 0

    local killed_any=false
    local pattern='scripts/run\.sh --benchmark|worker\.py|tsx.*src/server\.ts|node_modules/.bin/vite|ngrok http|cloudflared tunnel'
    for pid in $(pgrep -f "$pattern" 2>/dev/null); do
        [ "$pid" = "$$" ] && continue
        is_current_process_family "$pid" && continue

        local cmd
        cmd=$(ps -p "$pid" -o command= 2>/dev/null) || true
        if echo "$cmd" | grep -q "$PWD" || process_cwd_in_this_worktree "$pid"; then
            echo "🧹 Killing stale benchmark process from this worktree (PID $pid)"
            kill_stale_tree "$pid"
            killed_any=true
        fi
    done

    if $killed_any; then
        sleep 1
        for pid in $(pgrep -f "$pattern" 2>/dev/null); do
            [ "$pid" = "$$" ] && continue
            is_current_process_family "$pid" && continue
            if process_cwd_in_this_worktree "$pid"; then
                kill -9 "$pid" 2>/dev/null || true
            fi
        done
        echo "✅ Stale same-worktree benchmark processes stopped"
    fi
}

if [ "$BENCHMARK_ISOLATED_RUN" != "true" ]; then
    kill_stale_same_worktree_benchmark_stack
fi

# ── Cloud instance: aggressive port cleanup ──
# On cloud there's exactly one worktree — no multi-workspace concern.
# Kill everything on our port range to prevent zombie conflicts from prior
# run.sh invocations or crashed services. Retry until every port is free.

if $IS_CLOUD; then
    CLOUD_PORTS=($BACKEND_PORT $FRONTEND_PORT $HEALTH_PORT $SDK_METRICS_PORT $NGROK_WEB_PORT)

    kill_port() {
        local port=$1
        if command -v fuser >/dev/null 2>&1; then
            fuser -k "$port/tcp" 2>/dev/null || true
        else
            for pid in $(lsof -ti :"$port" 2>/dev/null); do
                kill -9 "$pid" 2>/dev/null || true
            done
        fi
    }

    port_in_use() {
        local port=$1
        if command -v fuser >/dev/null 2>&1; then
            fuser "$port/tcp" >/dev/null 2>&1
        else
            lsof -ti :"$port" >/dev/null 2>&1
        fi
    }

    # Phase 1: kill everything on service ports + known process patterns
    CLOUD_KILLED=false
    for port in "${CLOUD_PORTS[@]}"; do
        if port_in_use "$port"; then
            echo "🧹 Killing processes on port $port"
            kill_port "$port"
            CLOUD_KILLED=true
        fi
    done
    for pattern in "worker\.py" "tsx.*server\.ts" "npx vite" "run_local_worker"; do
        for pid in $(pgrep -f "$pattern" 2>/dev/null); do
            echo "🧹 Killing $pattern (PID $pid)"
            kill -9 "$pid" 2>/dev/null || true
            CLOUD_KILLED=true
        done
    done

    # Phase 2: retry until all ports are free (processes may linger briefly)
    if $CLOUD_KILLED; then
        MAX_PORT_RETRIES=10
        for attempt in $(seq 1 $MAX_PORT_RETRIES); do
            sleep 1
            ALL_FREE=true
            for port in "${CLOUD_PORTS[@]}"; do
                if port_in_use "$port"; then
                    ALL_FREE=false
                    echo "   port $port still held (attempt $attempt/$MAX_PORT_RETRIES) — force-killing"
                    kill_port "$port"
                fi
            done
            if $ALL_FREE; then
                echo "✅ All ports free"
                break
            fi
            if [ "$attempt" -eq "$MAX_PORT_RETRIES" ]; then
                echo "❌ Ports still occupied after $MAX_PORT_RETRIES retries:"
                for port in "${CLOUD_PORTS[@]}"; do
                    port_in_use "$port" && echo "   port $port: $(fuser "$port/tcp" 2>&1 || lsof -ti :"$port" 2>/dev/null)"
                done
                exit 1
            fi
        done
    fi
fi

# ── Pre-flight: ensure Postgres is available ──
# Prefer Docker (per-workspace container), fall back to system Postgres when
# the Docker daemon isn't available (sandboxed containers, CI without --privileged).
DB_CONTAINER="victoria-db-${CONDUCTOR_WORKSPACE_NAME}"
DB_VOLUME="victoria-pgdata-${CONDUCTOR_WORKSPACE_NAME}"
PRESTARTED_WORKSPACE_DB=false

workspace_db_container_owns_port() {
    local container_port
    container_port=$(docker inspect "$DB_CONTAINER" \
        --format='{{if .State.Running}}{{(index (index .HostConfig.PortBindings "5432/tcp") 0).HostPort}}{{end}}' \
        2>/dev/null || true)
    [ "$container_port" = "$LOCAL_DB_PORT" ]
}

# Probe the workspace-scoped database service itself before asking the whole
# Docker daemon for global state. Under concurrent deploy load `docker info`
# can miss its one-second responsiveness budget even while this already-started
# Postgres is healthy. Verify that the exact workspace-named container owns the
# expected host port before trusting the listener; another workspace can have
# valid victoria credentials on a stale inherited port.
if [ "${ROSE_USE_SYSTEM_PG:-false}" != "true" ] && \
   workspace_db_container_owns_port && \
   PGPASSWORD=postgres pg_isready -h localhost -p "$LOCAL_DB_PORT" -U postgres -d victoria -q 2>/dev/null; then
    PRESTARTED_WORKSPACE_DB=true
fi
DOCKER_OK=false
if ! $PRESTARTED_WORKSPACE_DB && \
   docker ps --filter "name=^${DB_CONTAINER}$" --format '{{.Names}}' 2>/dev/null | grep -q .; then
    # /deploy pre-starts this exact workspace container. Prefer that direct,
    # authoritative check even when a busy Docker Desktop daemon makes the
    # broader `docker info` probe miss its bounded response window.
    DOCKER_OK=true
elif ! $PRESTARTED_WORKSPACE_DB && docker_info_quick; then
    DOCKER_OK=true
fi

DB_OWNED_BY_US=false  # Track whether this run started/created the DB.
DB_OWNED_CONTAINER_ID=""
USE_SYSTEM_PG=false
SYSTEM_DB_OWNED_BY_US=false
LOCAL_DB_NAME="victoria"
LOCAL_DB_ACTUAL_PORT="$LOCAL_DB_PORT"
if [ "${ROSE_USE_SYSTEM_PG:-false}" = "true" ]; then
    USE_SYSTEM_PG=true
fi

cleanup_seed_bootstrap_database() {
    if $USE_SYSTEM_PG && $SYSTEM_DB_OWNED_BY_US; then
        PGPASSWORD=postgres dropdb -h localhost -p 5432 -U postgres --if-exists "$LOCAL_DB_NAME" >/dev/null 2>&1 || true
        SYSTEM_DB_OWNED_BY_US=false
        DB_OWNED_BY_US=false
    elif [ -n "$DB_OWNED_CONTAINER_ID" ]; then
        docker rm -f "$DB_CONTAINER" >/dev/null 2>&1 || true
        docker volume rm "$DB_VOLUME" >/dev/null 2>&1 || true
        DB_OWNED_CONTAINER_ID=""
        DB_OWNED_BY_US=false
    fi
}

fail_required_seed_dump() {
    echo "❌ $1" >&2
    echo "   Expected cache token: $_SEED_CACHE_TOKEN" >&2
    cleanup_seed_bootstrap_database
    exit 1
}

if $PRESTARTED_WORKSPACE_DB; then
    LOCAL_DB_URL="postgresql://postgres:postgres@localhost:$LOCAL_DB_PORT/victoria"
    echo "🐘 Reusing healthy workspace Postgres on port $LOCAL_DB_PORT (Docker daemon probe not required)"
elif $DOCKER_OK && ! $USE_SYSTEM_PG; then
    # ── Docker path (macOS / Linux with working Docker) ──
    if ! docker ps &>/dev/null 2>&1; then
        if [ -d "/Applications/Docker.app" ]; then
            echo "🐳 Docker not running — starting Docker Desktop..."
            open -a Docker
            for i in $(seq 1 60); do
                if docker ps &>/dev/null 2>&1; then
                    echo "🐳 Docker is ready"
                    break
                fi
                if [ "$i" -eq 60 ]; then
                    echo "⚠️  Docker did not start in 60s — local Postgres may fail"
                fi
                sleep 1
            done
        fi
    fi

    LOCAL_DB_URL="postgresql://postgres:postgres@localhost:$LOCAL_DB_PORT/victoria"

    # Helper: create (or recreate) the Postgres container with the correct port
    create_db_container() {
        docker rm -f "$DB_CONTAINER" 2>/dev/null || true
        docker run -d \
            --name "$DB_CONTAINER" \
            -e POSTGRES_PASSWORD=postgres \
            -e POSTGRES_DB=victoria \
            -p "$LOCAL_DB_PORT:5432" \
            -v "$DB_VOLUME:/var/lib/postgresql/data" \
            postgres:16-alpine >/dev/null
    }

    if docker ps --filter "name=^${DB_CONTAINER}$" --format '{{.Names}}' | grep -q .; then
        ACTUAL_PORT=$(docker port "$DB_CONTAINER" 5432 2>/dev/null | head -1 | grep -o '[0-9]*$' || true)
        if [ "$ACTUAL_PORT" = "$LOCAL_DB_PORT" ]; then
            echo "🐘 Local Postgres already running ($DB_CONTAINER on port $LOCAL_DB_PORT)"
        else
            echo "🐘 Postgres container on wrong port ($ACTUAL_PORT vs $LOCAL_DB_PORT) — recreating..."
            create_db_container
            DB_OWNED_BY_US=true
        fi
    elif docker ps -a --filter "name=^${DB_CONTAINER}$" --format '{{.Names}}' | grep -q .; then
        ACTUAL_PORT=$(docker inspect "$DB_CONTAINER" --format='{{(index (index .HostConfig.PortBindings "5432/tcp") 0).HostPort}}' 2>/dev/null || true)
        if [ "$ACTUAL_PORT" = "$LOCAL_DB_PORT" ]; then
            echo "🐘 Starting stopped Postgres container..."
            docker start "$DB_CONTAINER" >/dev/null
            DB_OWNED_BY_US=true
        else
            echo "🐘 Stopped container on wrong port ($ACTUAL_PORT vs $LOCAL_DB_PORT) — recreating..."
            create_db_container
            DB_OWNED_BY_US=true
        fi
    else
        echo "🐘 Creating local Postgres container..."
        create_db_container
        DB_OWNED_BY_US=true
    fi

    if $DB_OWNED_BY_US; then
        DB_OWNED_CONTAINER_ID="$(docker inspect --format='{{.Id}}' "$DB_CONTAINER")"
    fi

    # Wait for Postgres to accept connections
    echo -n "   Waiting for Postgres..."
    for i in $(seq 1 30); do
        if docker exec "$DB_CONTAINER" pg_isready -U postgres -q 2>/dev/null; then
            echo " ready (${i}s)"
            break
        fi
        if [ "$i" -eq 30 ]; then
            echo " ❌ timed out"
            exit 1
        fi
        sleep 1
    done
else
    # ── System Postgres fallback (no Docker) ──
    USE_SYSTEM_PG=true
    SYSTEM_PG_PORT=5432
    LOCAL_DB_ACTUAL_PORT="$SYSTEM_PG_PORT"
    if [ "$BENCHMARK_ISOLATED_RUN" = "true" ] && [ -n "${BENCHMARK_RUN_ID:-}" ]; then
        SAFE_BENCHMARK_RUN_ID=$(printf '%s' "$BENCHMARK_RUN_ID" | tr -c '[:alnum:]' '_')
        LOCAL_DB_NAME="victoria_bench_${SAFE_BENCHMARK_RUN_ID}"
    fi
    LOCAL_DB_URL="postgresql://postgres:postgres@localhost:$SYSTEM_PG_PORT/$LOCAL_DB_NAME"

    if pg_isready -h localhost -p "$SYSTEM_PG_PORT" -U postgres -q 2>/dev/null; then
        echo "🐘 System Postgres already running on port $SYSTEM_PG_PORT"
    else
        echo "🐘 Starting system Postgres..."
        PG_VER=$(pg_lsclusters -h 2>/dev/null | head -1 | awk '{print $1}')
        if [ -n "$PG_VER" ]; then
            pg_ctlcluster "$PG_VER" main start 2>/dev/null || service postgresql start 2>/dev/null || true
        else
            service postgresql start 2>/dev/null || true
        fi
        # Wait for it
        echo -n "   Waiting for Postgres..."
        for i in $(seq 1 30); do
            if pg_isready -h localhost -p "$SYSTEM_PG_PORT" -U postgres -q 2>/dev/null; then
                echo " ready (${i}s)"
                break
            fi
            if [ "$i" -eq 30 ]; then
                echo " ❌ No Docker and system Postgres failed to start."
                echo "   Run scripts/cloud-build.sh to install Postgres."
                exit 1
            fi
            sleep 1
        done
    fi
    if [ "$BENCHMARK_ISOLATED_RUN" = "true" ]; then
        PGPASSWORD=postgres dropdb -h localhost -U postgres --if-exists "$LOCAL_DB_NAME" >/dev/null 2>&1 || true
        PGPASSWORD=postgres createdb -h localhost -U postgres "$LOCAL_DB_NAME"
        SYSTEM_DB_OWNED_BY_US=true
        DB_OWNED_BY_US=true
        echo "🐘 Created isolated system database $LOCAL_DB_NAME"
    else
        PGPASSWORD=postgres psql -h localhost -U postgres -tc "SELECT 1 FROM pg_database WHERE datname='$LOCAL_DB_NAME'" 2>/dev/null \
            | grep -q 1 || PGPASSWORD=postgres createdb -h localhost -U postgres "$LOCAL_DB_NAME" 2>/dev/null || true
    fi
fi

# Fast Mode cache is intentionally shared across local/dev/prod so recorded runs
# survive local DB resets. Capture the prod DB URL from back-end/.env before this
# script overwrites DATABASE_URL with the local app database below.
#
# FAST_MODE_CACHE_USE_LOCAL=1 routes the fast-cache at the isolated LOCAL DB
# instead of the shared prod Supabase pooler. The shared pooler has a fixed
# connection ceiling; when many local stacks (or a cloud fleet) run at once it
# saturates, and the boot-time "Ensuring Fast Mode cache schema" step fails with
# EMAXCONN / pool-timeout — blocking the stack from ever starting. For a smoke
# gate that only needs a working runtime (not prod cache sharing), point the
# cache at the local DB so startup can't be held hostage by pooler contention.
if [ "${FAST_MODE_CACHE_USE_LOCAL:-}" = "1" ] && [ -z "${FAST_MODE_CACHE_DATABASE_URL:-}" ]; then
    # Fail closed: without a real LOCAL_DB_URL, exporting an empty value would let
    # the block below silently re-derive the prod pooler URL — defeating the whole
    # point of the flag. Require it explicitly.
    if [ -z "${LOCAL_DB_URL:-}" ]; then
        echo "❌ FAST_MODE_CACHE_USE_LOCAL=1 requires LOCAL_DB_URL (isolated local DB) to be set" >&2
        exit 1
    fi
    export FAST_MODE_CACHE_DATABASE_URL="$LOCAL_DB_URL"
    echo "🧠 FAST_MODE_CACHE_USE_LOCAL=1 — routing Fast Mode cache at the isolated local DB (decoupled from the shared prod pooler)"
fi
if [ -z "${FAST_MODE_CACHE_DATABASE_URL:-}" ] && [ -f "back-end/.env" ]; then
    PROD_CACHE_DATABASE_URL=$(python3 - <<'PY'
from pathlib import Path

for raw in Path("back-end/.env").read_text().splitlines():
    line = raw.strip()
    if not line or line.startswith("#") or "=" not in line:
        continue
    key, value = line.split("=", 1)
    if key.strip() != "DATABASE_URL":
        continue
    value = value.strip()
    if (value.startswith('"') and value.endswith('"')) or (value.startswith("'") and value.endswith("'")):
        value = value[1:-1]
    print(value)
    break
PY
)
    if [ -n "$PROD_CACHE_DATABASE_URL" ]; then
        export FAST_MODE_CACHE_DATABASE_URL="$PROD_CACHE_DATABASE_URL"
    fi
fi
if [ -z "${FAST_MODE_CACHE_DATABASE_URL:-}" ]; then
    echo "❌ FAST_MODE_CACHE_DATABASE_URL is required; Fast Mode cache must route to the prod cache table."
    echo "   Set it explicitly or keep the prod DATABASE_URL in back-end/.env so scripts/run.sh can derive it before local DB override."
    exit 1
fi
echo "🧠 Ensuring Fast Mode cache schema..."
# This ensure connects to FAST_MODE_CACHE_DATABASE_URL — the SHARED prod pooler by
# default (see above). When a cloud fleet boots concurrently (plus any neighbor
# fleet on the same app), the pooler briefly saturates and this single query dies
# with "Timed out fetching a new connection from the connection pool" → under
# `set -e` the WHOLE stack aborts before the barrier (observed: 8/8 boxes lost to a
# transient pooler spike while a 50-machine neighbor fleet held connections). The
# op is idempotent (CREATE TABLE/INDEX IF NOT EXISTS), so retry with backoff and
# let the transient saturation drain — same resilience the seed/cred syncs already have.
if ! ensure_fast_mode_cache_schema bash -c \
    'cd back-end && npx tsx scripts/ensure-fast-mode-cache-schema.ts'; then
    exit 1
fi

# Larger Prisma pool: Fast Mode adds cache get/set on every LLM call, which under
# sub-agent fan-out competes with the agent's own writes for the connection pool
# (the known P2024 timeout signature). A bigger local pool absorbs the burst.
export DATABASE_URL="${LOCAL_DB_URL}?connection_limit=50&pool_timeout=30"
export DIRECT_URL="$LOCAL_DB_URL"

# Fast DB warm-start (cloud pool): the schema push + 10k-people seed cost ~50s and
# run on EVERY boot because the box DB lives on ephemeral rootfs (resets on Fly
# stop/start). BENCHMARK_SEED_DUMP points at a pg_dump on the PERSISTENT /data
# volume; when it exists and the schema is unchanged, restore it (~fast COPY) and
# skip BOTH the push and the seed. First run seeds normally, then writes the dump
# for every later claim of that machine. Unset (local dev) → zero behaviour change.
DB_RESTORED=false
FIRST_RUN_SEEDED=false
_SEED_DUMP="${BENCHMARK_SEED_DUMP:-}"
_SCHEMA_HASH="$( (shasum back-end/prisma/schema.prisma 2>/dev/null || sha1sum back-end/prisma/schema.prisma 2>/dev/null) | awk '{print $1}')"
# Cross-clone seed-dump cache (R2): a freshly-cloned cloud guest's /data has no
# local dump, so without this it pays the full ~19-min prod cold-sync every time.
# Pull a schema-matched dump from the SHARED cache first. This is purely additive
# and neighbor-safe: on any miss/error $_SEED_DUMP stays absent and the block
# below cold-syncs exactly as before (then repopulates the cache); the schemahash
# guard + pg_restore fallback catch any mismatch/corruption, so it can never break
# a boot or disturb a concurrently-running fleet. Token = schema hash (correctness)
# + UTC day (bounds staleness to 24h). Local dev leaves BENCHMARK_SEED_DUMP unset.
_SEED_CACHE_TOKEN="${_SCHEMA_HASH}-$(date -u +%Y%m%d 2>/dev/null || echo undated)"
# R2 creds live in back-end/.env (run.sh does not export them to its shell), so
# gate on the file, not the environment. seed-dump-cache.ts loads the .env itself.
_SEED_CACHE_ENABLED=0
grep -qE '^R2_BUCKET_TRACE_ARCHIVE=.' back-end/.env 2>/dev/null && _SEED_CACHE_ENABLED=1
_SEED_LOCK_HELD=0
release_seed_lock_if_held() {
    if [ "${_SEED_LOCK_HELD:-0}" = "1" ]; then
        release_benchmark_seed_lock "$_SEED_DUMP"
        _SEED_LOCK_HELD=0
    fi
}
trap release_seed_lock_if_held EXIT

# BEGIN BENCHMARK_SEED_CONSUMER_CRITICAL_SECTION
# Hold the pair lock through decision, optional R2 replacement, and synchronous
# pg_restore. Merely waiting for a producer and then reading was a TOCTOU race:
# another producer could replace the pair between the wait and restore.
if [ -n "$_SEED_DUMP" ]; then
    acquire_benchmark_seed_lock "$_SEED_DUMP"
    _SEED_LOCK_HELD=1
fi
# Decide where the seeded DB comes from (scripts/lib/seed-cache.sh). A stale dump
# baked into the warm snapshot must fall through to the shared cache, NOT shadow
# it — the old `[ ! -s ]` guard skipped the download whenever ANY dump existed, so
# a hash-mismatched snapshot dump cold-synced every clone and starved the barrier.
_SEED_DECISION="$(seed_cache_decision "$_SEED_DUMP" "$_SCHEMA_HASH" "$_SEED_CACHE_ENABLED")"
if [ "$_SEED_DECISION" = "consult-remote" ]; then
    # Drop any stale local dump so a clean cache object lands in its place.
    rm -f "$_SEED_DUMP" "${_SEED_DUMP}.schemahash" 2>/dev/null || true
    echo "🔎 Checking shared seed-dump cache ($_SEED_CACHE_TOKEN)..."
    if (cd back-end && npx tsx scripts/seed-dump-cache.ts get "$_SEED_CACHE_TOKEN" "$_SEED_DUMP") 2>/dev/null && [ -s "$_SEED_DUMP" ]; then
        printf '%s' "$_SCHEMA_HASH" > "${_SEED_DUMP}.schemahash"
        _SEED_DECISION="restore-local"
        echo "   ✅ pulled cached seed dump ($(du -h "$_SEED_DUMP" 2>/dev/null | awk '{print $1}')) — restoring instead of cold-syncing"
    else
        rm -f "$_SEED_DUMP" "${_SEED_DUMP}.schemahash" 2>/dev/null || true
        echo "   ℹ️ no cached dump for this schema/day — will cold-sync and populate it"
    fi
fi
if [ "${BENCHMARK_REQUIRE_SEED_DUMP:-0}" = "1" ] && [ "$_SEED_DECISION" != "restore-local" ]; then
    fail_required_seed_dump "Isolated local benchmarks require a schema-matched seed dump; refusing a slow production cold-sync."
fi
if [ "$_SEED_DECISION" = "restore-local" ] && [ -n "$_SEED_DUMP" ] && [ -s "$_SEED_DUMP" ]; then
    echo "🗜️  Restoring seeded DB from persistent dump ($_SEED_DUMP) — skipping schema push + seed..."
    _SEED_RESTORE_CONTAINER=""
    if ! $USE_SYSTEM_PG; then
        _SEED_RESTORE_CONTAINER="$DB_CONTAINER"
    fi
    if PGPASSWORD=postgres bash scripts/restore-seed-dump.sh \
        "$_SEED_DUMP" localhost "$LOCAL_DB_ACTUAL_PORT" postgres "$LOCAL_DB_NAME" \
        "$_SEED_RESTORE_CONTAINER" >/dev/null; then
        DB_RESTORED=true
        echo "   ✅ DB restored from dump"
    else
        echo "   ⚠️ restore failed — falling back to push + seed"
        # The target database's own pg_restore just proved this archive bad.
        # Invalidate it so a failed regeneration cannot make every later boot
        # retry the same unreadable archive and matching schema sidecar.
        rm -f "$_SEED_DUMP" "${_SEED_DUMP}.schemahash" 2>/dev/null || true
        if [ "${BENCHMARK_REQUIRE_SEED_DUMP:-0}" = "1" ]; then
            fail_required_seed_dump "Required isolated benchmark seed dump could not be restored; refusing a slow production cold-sync."
        fi
    fi
fi
release_seed_lock_if_held
# END BENCHMARK_SEED_CONSUMER_CRITICAL_SECTION

if $DB_RESTORED; then
    # A restored dump USUALLY already carries the Message trgm/grep indexes, but a
    # dump published by an older box (before this step existed) or a partially-
    # applied restore can lack them — so re-ensure idempotently. This gives the
    # fast-restore path the SAME backend-ready schema as the cold-sync (else) path,
    # which runs this same step, rather than a subtly different DB.
    echo "🔎 Ensuring agent-network grep indexes (post-restore)..."
    (cd back-end && npx tsx scripts/ensure-agent-network-grep-indexes.ts)
else

# Sync Prisma schema to local DB (idempotent, dev-only)
echo "🐘 Syncing Prisma schema..."
(cd back-end && npx prisma db push --skip-generate --accept-data-loss 2>&1 | tail -3)
echo "🔎 Ensuring agent-network grep indexes..."
(cd back-end && npx tsx scripts/ensure-agent-network-grep-indexes.ts)

# Seed local DB if dev user doesn't exist yet (full prod sync in scripts/setup-db.sh)
if $DOCKER_OK && ! $USE_SYSTEM_PG; then
    USER_EXISTS=$(docker exec "$DB_CONTAINER" psql -U postgres -d "$LOCAL_DB_NAME" -tAc \
      "SELECT COUNT(*) FROM \"User\" WHERE \"userId\" = '1f85ff25-6e29-4c1b-8739-f917bd101a30'" 2>/dev/null | tr -d ' ' || echo "0")
else
    USER_EXISTS=$(PGPASSWORD=postgres psql -h localhost -U postgres -d "$LOCAL_DB_NAME" -tAc \
      "SELECT COUNT(*) FROM \"User\" WHERE \"userId\" = '1f85ff25-6e29-4c1b-8739-f917bd101a30'" 2>/dev/null | tr -d ' ' || echo "0")
fi
if [ "$USER_EXISTS" = "0" ]; then
    echo "🌱 Syncing production data to local database (first run)..."
    # Retry the seed on a transient crash. At cloud fleet width this tsx/node
    # process intermittently SIGSEGVs a few seconds in (observed rc=139 ~11s after
    # stack launch — not deterministic, or every box would fail), and under
    # `set -eo pipefail` a single crash killed the ENTIRE stack → "stack process
    # exited before becoming healthy" → the box dropped from the batch (an infra
    # loss, not a benchmark verdict). Retry a few times before giving up so a
    # one-off native crash doesn't cost a whole box.
    # Capture the seed's OWN status. `$?` read after `fi` is the *if statement's*
    # status — which is 0 whenever the condition was false and there is no else —
    # so the real signal (137 = SIGKILL/OOM, 139 = SIGSEGV) was reported as
    # "rc=0" and every diagnosis started from a lie.
    _seed_ok=0
    for _seed_try in 1 2 3; do
        _seed_rc=0
        (cd back-end && npx tsx scripts/seed-local.ts) || _seed_rc=$?
        if [ "$_seed_rc" = 0 ]; then _seed_ok=1; break; fi
        _seed_signal=""
        case "$_seed_rc" in
            137) _seed_signal=" = SIGKILL (out of memory — check dmesg for oom-kill)" ;;
            139) _seed_signal=" = SIGSEGV" ;;
        esac
        if [ "$_seed_try" -lt 3 ]; then
            echo "   ⚠️ first-run seed attempt ${_seed_try}/3 failed (rc=${_seed_rc}${_seed_signal}) — retrying..."
        else
            echo "   ⚠️ first-run seed attempt ${_seed_try}/3 failed (rc=${_seed_rc}${_seed_signal}) — attempts exhausted"
        fi
        sleep $(( _seed_try * 3 ))
    done
    [ "$_seed_ok" = 1 ] || { echo "❌ first-run seed failed after 3 attempts — aborting stack"; exit 1; }
    FIRST_RUN_SEEDED=true
elif [ "${BENCHMARK_WORLD_MODEL_MODE:-}" = "simulate" ]; then
    # Simulate mode: the World Model Harness intercepts every environment-boundary
    # tool, so real browser cookies/passwords are never exercised. Re-syncing all
    # 21k+ cookie rows on every stack start is pure overhead (and stalls on a
    # throttled cloud uplink). Compute tokens stay fresh via run_benchmark's
    # run-level infrastructure preflight, so skip browser auth sync here.
    echo "🌍 simulate mode — skipping startup browser credential sync (WMH mocks env tools)"
else
    echo "🌱 Local database already seeded; syncing browser credentials..."
    # Same transient-SIGSEGV resilience as the first-run seed above.
    _cred_ok=0
    for _cred_try in 1 2 3; do
        if (cd back-end && npx tsx scripts/seed-local.ts --credentials-only); then _cred_ok=1; break; fi
        _cred_rc=$?
        echo "   ⚠️ credential sync attempt ${_cred_try}/3 failed (rc=${_cred_rc}$([ "$_cred_rc" = 139 ] && echo ' = SIGSEGV')) — retrying..."
        sleep $(( _cred_try * 3 ))
    done
    [ "$_cred_ok" = 1 ] || { echo "❌ credential sync failed after 3 attempts — aborting stack"; exit 1; }
fi

# Persist a dump on /data so the NEXT claim of this machine restores in seconds
# instead of re-seeding. Best-effort; the schemahash guards against schema drift.
if [ -n "$_SEED_DUMP" ]; then
    echo "🗜️  Saving seed dump for fast future warm-starts ($_SEED_DUMP)..."
    acquire_benchmark_seed_lock "$_SEED_DUMP"
    _SEED_LOCK_HELD=1
    _SEED_DUMP_CONTAINER=""
    if ! $USE_SYSTEM_PG; then
        _SEED_DUMP_CONTAINER="$DB_CONTAINER"
    fi
    if PGPASSWORD=postgres bash scripts/save-seed-dump.sh \
        "$_SEED_DUMP" localhost "$LOCAL_DB_ACTUAL_PORT" postgres "$LOCAL_DB_NAME" \
        "$_SEED_DUMP_CONTAINER"; then
        printf '%s' "$_SCHEMA_HASH" > "${_SEED_DUMP}.schemahash"
        echo "   ✅ seed dump saved ($(du -h "$_SEED_DUMP" 2>/dev/null | awk '{print $1}'))"
        # Publish to the shared cache so the NEXT clone (any workspace — including a
        # neighbor's daily run) restores in seconds instead of cold-syncing. Best-
        # effort; a failed upload never blocks the boot.
        if [ "$_SEED_CACHE_ENABLED" = 1 ]; then
            if (cd back-end && npx tsx scripts/seed-dump-cache.ts put "$_SEED_CACHE_TOKEN" "$_SEED_DUMP") >/dev/null 2>&1; then
                echo "   ☁️ published seed dump to shared cache ($_SEED_CACHE_TOKEN)"
            fi
        fi
    else
        echo "   ⚠️ seed dump save failed; no partial archive was published"
    fi
    release_seed_lock_if_held
fi

fi   # end: if $DB_RESTORED / else (push + seed + dump)

# Restored dumps and schema pushes must both carry the hand-written production
# functions/triggers that Prisma cannot represent.
(cd back-end && DB_CONTAINER="$DB_CONTAINER" LOCAL_DB_NAME="$LOCAL_DB_NAME" \
    bash scripts/apply-local-workflow-ddl.sh)

# ── Pre-flight: ensure node_modules exist for all JS services ──
JS_SVC_DIRS=(back-end front-end)
if ! $BENCHMARK_MODE && $IS_MAC; then
    JS_SVC_DIRS+=(mac-app)
fi
bash "$SCRIPT_DIR/ensure-workspace-dependencies.sh" "${JS_SVC_DIRS[@]}"

# ── Pre-flight: ensure agents venv exists with deps installed ──
if [ ! -f agents/venv/bin/activate ] || ! agents/venv/bin/python -c "import temporalio" 2>/dev/null; then
    echo "🐍 Setting up agents virtualenv..."
    PYTHON_VERSION=$(cat agents/.python-version 2>/dev/null || echo "3.11")
    # Try asdf python first, then system python3
    PYTHON_BIN="$(asdf where python "$PYTHON_VERSION" 2>/dev/null)/bin/python3" || true
    if [ ! -x "$PYTHON_BIN" ]; then
        PYTHON_BIN=$(command -v python3)
    fi
    echo "   Using: $PYTHON_BIN ($($PYTHON_BIN --version 2>&1))"
    if [ ! -f agents/venv/bin/activate ]; then
        (cd agents && "$PYTHON_BIN" -m venv venv)
    fi
    (cd agents && source venv/bin/activate && pip install -r requirements.txt)
    echo "🐍 Agents venv ready"
fi

# Pre-flight: handle processes on our ports from this worktree.
# Cloud instances already handled above (aggressive cleanup). This block
# handles macOS multi-worktree scenarios where we must distinguish our
# processes from another workspace's.
if ! $IS_CLOUD; then
    SERVICE_PORTS=($BACKEND_PORT $FRONTEND_PORT $HEALTH_PORT $SDK_METRICS_PORT $NGROK_WEB_PORT)
    $IS_MAC && SERVICE_PORTS+=($MAC_APP_PORT)
    for port in "${SERVICE_PORTS[@]}"; do
        for pid in $(lsof -nP -tiTCP:"$port" -sTCP:LISTEN 2>/dev/null); do
            cmd=$(ps -p "$pid" -o command= 2>/dev/null) || true
            echo "$cmd" | grep -qi docker && continue
            if process_belongs_to_this_worktree "$pid"; then
                continue
            fi
            echo "❌ Port $port in use by unknown process (PID $pid). Kill it manually or choose a different port range."
            exit 1
        done
    done
    if [ "$BENCHMARK_ISOLATED_RUN" = "true" ]; then
        echo "🧹 Isolated benchmark run: skipping same-worktree service sweep"
    else
        echo "🧹 Cleaning stale services for this worktree before startup..."
        bash "$SCRIPT_DIR/kill-services.sh" || exit 1
    fi
fi

PIDS=()
NAMES=()
NGROK_PID=""
NGROK_CONFIG_FILE=""
PUBLIC_TUNNEL_SERVICE_NAME=""
SHUTTING_DOWN=false
SERVICE_STATUS=starting

dns_label_from_workspace() {
    python3 - <<'PY'
import os
import re
import sys

raw = os.environ.get("CONDUCTOR_WORKSPACE_NAME", "").strip()
if not raw:
    sys.exit("CONDUCTOR_WORKSPACE_NAME is required to derive a stable public domain")
label = re.sub(r"[^a-z0-9-]+", "-", raw.lower()).strip("-")
label = re.sub(r"-+", "-", label)
if not label:
    sys.exit(f"CONDUCTOR_WORKSPACE_NAME={raw!r} does not contain DNS-safe characters")
print(label[:50].strip("-"))
PY
}

# Reserve an ngrok domain, defaulting to this worktree's primary domain.
# Callers may pass an explicit domain (the smoke fallback reserves its own) and
# may pass `soft` to warn instead of exiting when reservation fails, so a
# best-effort fallback path never kills the whole stack.
ensure_ngrok_domain_reserved() {
    local domain="${1:-$WORKTREE_DOMAIN}"
    local failure_mode="${2:-fatal}"
    if [ -z "${NGROK_API_KEY:-}" ]; then
        return 0
    fi
    echo "🌐 Checking ngrok reserved domain $domain"
    local domains_json
    domains_json=$(ngrok api reserved-domains list --api-key "$NGROK_API_KEY" --limit 1000 2>&1) || {
        echo "$domains_json"
        echo "❌ Could not list ngrok reserved domains with NGROK_API_KEY."
        [ "$failure_mode" = "soft" ] && return 1
        exit 1
    }
    if printf '%s\n' "$domains_json" | grep -q "\"domain\"[[:space:]]*:[[:space:]]*\"$domain\""; then
        echo "🌐 Reserved domain already exists: $domain"
        return 0
    fi
    echo "🌐 Reserving ngrok domain $domain"
    local create_output
    create_output=$(ngrok api reserved-domains create \
        --api-key "$NGROK_API_KEY" \
        --domain "$domain" \
        --description "Conductor workspace $CONDUCTOR_WORKSPACE_NAME public frontend" 2>&1) || {
        echo "$create_output"
        echo "❌ Could not reserve $domain. Confirm the ngrok account is on Pay-as-you-go and the domain is available."
        [ "$failure_mode" = "soft" ] && return 1
        exit 1
    }
}

# Cloudflare account-less quick tunnels have no uptime guarantee: a hostname is
# published within ~2s but a meaningful fraction never route at all (DNS answers
# with Cloudflare IPs, yet every request fails to connect indefinitely), and the
# service also rate-limits bursts of tunnel creation. Publication alone was
# treated as readiness here, so a dead tunnel was only discovered ~60s later by
# the public-tunnel smoke — which fatally tore down the whole stack with no
# retry. Verify the edge actually routes, and recycle the tunnel when it does not.
#
# Any HTTP status proves the edge routes to us; the origin frontend is not up yet
# at this point, so 502/404 are perfectly acceptable here. Only "no HTTP response
# at all" (curl writes 000) means the hostname is dead.
CLOUDFLARE_TUNNEL_EDGE_TIMEOUT_SECONDS="${CLOUDFLARE_TUNNEL_EDGE_TIMEOUT_SECONDS:-45}"
CLOUDFLARE_TUNNEL_MAX_ATTEMPTS="${CLOUDFLARE_TUNNEL_MAX_ATTEMPTS:-3}"
# Linear backoff base; attempt N waits N × this before re-requesting.
CLOUDFLARE_TUNNEL_RETRY_BACKOFF_SECONDS="${CLOUDFLARE_TUNNEL_RETRY_BACKOFF_SECONDS:-20}"

cloudflare_tunnel_edge_is_routing() {
    local url="$1" deadline=$((SECONDS + CLOUDFLARE_TUNNEL_EDGE_TIMEOUT_SECONDS)) status
    local retry_seconds="${CLOUDFLARE_TUNNEL_EDGE_RETRY_SECONDS:-2}"
    while [ "$SECONDS" -lt "$deadline" ]; do
        # --noproxy '*': this probe must measure the Cloudflare edge itself, not
        # an inherited HTTP(S)_PROXY/ALL_PROXY. A proxy corrupts the result in
        # BOTH directions — it can answer 407/5xx and fake a healthy tunnel, or
        # (as on a macOS host with a content blocker configured system-wide)
        # refuse trycloudflare.com outright and report a healthy tunnel as dead.
        status="$(curl -s -o /dev/null -w '%{http_code}' --noproxy '*' --max-time 10 "$url" 2>/dev/null || true)"
        if [ -n "$status" ] && [ "$status" != "000" ]; then
            return 0
        fi
        sleep "$retry_seconds"
    done
    return 1
}

start_cloudflare_quick_tunnel() {
    if ! command -v cloudflared >/dev/null 2>&1; then
        echo "❌ cloudflared is required for isolated benchmark public tunnels."
        exit 1
    fi
    mkdir -p "$RUN_CONTEXT_DIR"
    local tunnel_home="$RUN_CONTEXT_DIR/cloudflared-home"
    mkdir -p "$tunnel_home"
    PUBLIC_TUNNEL_SERVICE_NAME="cloudflared"

    local tunnel_attempt tunnel_log published
    for tunnel_attempt in $(seq 1 "$CLOUDFLARE_TUNNEL_MAX_ATTEMPTS"); do
        tunnel_log="$RUN_CONTEXT_DIR/cloudflared.log"
        [ "$tunnel_attempt" -gt 1 ] && tunnel_log="$RUN_CONTEXT_DIR/cloudflared.attempt${tunnel_attempt}.log"

        echo "🌐 Starting run-scoped public frontend tunnel → localhost:$FRONTEND_PORT (attempt $tunnel_attempt/$CLOUDFLARE_TUNNEL_MAX_ATTEMPTS)"
        HOME="$tunnel_home" cloudflared tunnel --no-autoupdate --url "http://127.0.0.1:$FRONTEND_PORT" \
            > "$tunnel_log" 2>&1 &
        NGROK_PID=$!
        PIDS+=($NGROK_PID); NAMES+=("$PUBLIC_TUNNEL_SERVICE_NAME")

        published=false
        for attempt in $(seq 1 60); do
            if ! kill -0 "$NGROK_PID" 2>/dev/null; then
                echo "⚠️  cloudflared exited before publishing a tunnel (attempt $tunnel_attempt)."
                tail -40 "$tunnel_log" || true
                break
            fi
            if cloudflare_publish_reported_environment "$tunnel_log" "$ALLOWED_ORIGINS"; then
                published=true
                break
            fi
            sleep 1
        done

        if [ "$published" = true ]; then
            echo "🔎 Verifying the tunnel edge routes: $PUBLIC_BASE_URL"
            if cloudflare_tunnel_edge_is_routing "$PUBLIC_BASE_URL"; then
                echo "🌐 Public tunnel ready: $PUBLIC_BASE_URL"
                return 0
            fi
            echo "⚠️  $PUBLIC_BASE_URL never routed within ${CLOUDFLARE_TUNNEL_EDGE_TIMEOUT_SECONDS}s; recycling the quick tunnel."
        fi

        # Retire this hostname before asking Cloudflare for a new one, so the dead
        # tunnel cannot linger in PIDS and be reported as a live service.
        kill "$NGROK_PID" 2>/dev/null || true
        wait "$NGROK_PID" 2>/dev/null || true
        unset 'PIDS[${#PIDS[@]}-1]' 'NAMES[${#NAMES[@]}-1]'
        NGROK_PID=""

        # Back off before re-requesting. Consecutive dead tunnels usually mean the
        # account-less service is rate-limiting this IP rather than that one
        # hostname was unlucky, and hammering it immediately keeps us limited.
        if [ "$tunnel_attempt" -lt "$CLOUDFLARE_TUNNEL_MAX_ATTEMPTS" ]; then
            local backoff=$((CLOUDFLARE_TUNNEL_RETRY_BACKOFF_SECONDS * tunnel_attempt))
            echo "⏳ Backing off ${backoff}s before requesting another quick tunnel..."
            sleep "$backoff"
        fi
    done

    echo "⚠️  cloudflared could not obtain a routable quick tunnel for :$FRONTEND_PORT after $CLOUDFLARE_TUNNEL_MAX_ATTEMPTS attempts."
    echo "   trycloudflare.com is account-less and best-effort."
    return 1
}

# Fallback provider when trycloudflare is unavailable.
#
# trycloudflare.com has no uptime guarantee and can refuse to route EVERY quick
# tunnel from a host for hours at a stretch (observed 2026-07-27: tunnels
# register, then Cloudflare terminates them or never routes the hostname, across
# both QUIC and HTTP/2). That used to fail the entire Pre-Deploy smoke gate with
# no recourse. ngrok is already a supported provider here and uses independent
# infrastructure, so an ephemeral ngrok endpoint is a clean second source.
#
# Uses a reserved per-worktree fallback domain, NOT a bare `ngrok http`.
#
# A bare agent binds the account's single free static endpoint, so two worktrees
# that both fell back at once collided with ERR_NGROK_334 and the second one's
# whole stack died (observed 2026-07-28: an ashgabat smoke run lost the endpoint
# to a concurrent port-vila deploy). We are on a paid plan and already reserve
# `rose-<worktree>` for the primary tunnel, so the fallback reserves its own
# `rose-<worktree>-bench` — distinct from the primary so a worktree's Step 5
# stack and its isolated benchmark stack can hold tunnels simultaneously.
#
# Reservation is best-effort: without NGROK_API_KEY (or if the API refuses) this
# still falls back to a bare agent, which works fine for a lone worktree.
start_ngrok_ephemeral_tunnel() {
    command -v ngrok >/dev/null 2>&1 || {
        echo "   ngrok fallback unavailable: ngrok is not installed."
        return 1
    }
    if [ -z "${NGROK_AUTHTOKEN:-}" ] && ! ngrok config check >/dev/null 2>&1; then
        echo "   ngrok fallback unavailable: no authtoken configured."
        return 1
    fi

    mkdir -p "$RUN_CONTEXT_DIR"
    local ngrok_log="$RUN_CONTEXT_DIR/ngrok-fallback.log"

    # Always name the endpoint. Pre-reservation needs NGROK_API_KEY (which lives
    # in back-end/.env and is NOT in this script's environment on the benchmark
    # path), but --domain works without it on our plan — the primary tunnel below
    # relies on exactly that. Gating the domain on the API key would silently
    # drop every fallback back onto the shared free endpoint, which is the
    # collision this is here to prevent.
    local fallback_label fallback_domain
    fallback_label="$(dns_label_from_workspace)" || return 1
    fallback_domain="rose-${fallback_label}-bench.${NGROK_DOMAIN_SUFFIX:-ngrok.app}"
    if [ -n "${NGROK_API_KEY:-}" ]; then
        ensure_ngrok_domain_reserved "$fallback_domain" soft ||
            echo "   Proceeding without pre-reservation of $fallback_domain."
    fi

    local -a ngrok_args=("http" "$FRONTEND_PORT")
    if [ -n "$fallback_domain" ]; then
        ngrok_args+=("--domain" "$fallback_domain")
        echo "🌐 Falling back to ngrok (reserved $fallback_domain) → localhost:$FRONTEND_PORT"
    else
        echo "🌐 Falling back to an ephemeral ngrok tunnel → localhost:$FRONTEND_PORT"
    fi

    ngrok "${ngrok_args[@]}" \
        --log stdout --log-format json --log-level info > "$ngrok_log" 2>&1 &
    NGROK_PID=$!
    PUBLIC_TUNNEL_SERVICE_NAME="ngrok"
    PIDS+=($NGROK_PID); NAMES+=("$PUBLIC_TUNNEL_SERVICE_NAME")

    local ngrok_url=""
    for attempt in $(seq 1 45); do
        if ! kill -0 "$NGROK_PID" 2>/dev/null; then
            echo "❌ ngrok exited before publishing a tunnel."
            tail -20 "$ngrok_log" || true
            return 1
        fi
        ngrok_url="$(grep -oE '"url":"https://[^"]+"' "$ngrok_log" 2>/dev/null |
            head -1 | sed 's/"url":"//; s/"$//')"
        [ -n "$ngrok_url" ] && break
        sleep 1
    done
    [ -n "$ngrok_url" ] || {
        echo "❌ ngrok did not publish an HTTPS endpoint."
        tail -20 "$ngrok_log" || true
        return 1
    }

    public_tunnel_publish_environment "$ngrok_url" "$ALLOWED_ORIGINS" || {
        echo "❌ ngrok published an unusable origin: $ngrok_url"
        return 1
    }

    echo "🔎 Verifying the ngrok edge routes: $PUBLIC_BASE_URL"
    cloudflare_tunnel_edge_is_routing "$PUBLIC_BASE_URL" || {
        echo "❌ $PUBLIC_BASE_URL never routed."
        return 1
    }
    echo "🌐 Public tunnel ready (ngrok): $PUBLIC_BASE_URL"
    return 0
}

# start_ngrok_public_tunnel is fatal by design in the normal `ngrok` mode: a dev
# stack with no public origin is unusable. But it is ALSO the last-resort
# fallback in cloudflare mode, where its `exit 1` would kill run.sh instead of
# letting the caller report "tried all providers". Setting this to 1 converts
# those exits into a plain non-zero return so the caller can keep control.
NGROK_PUBLIC_TUNNEL_NONFATAL=0

ngrok_public_tunnel_fail() {
    printf '%s\n' "$1" >&2
    [ "${NGROK_PUBLIC_TUNNEL_NONFATAL:-0}" = "1" ] && return 1
    exit 1
}

# An ephemeral ngrok attempt can fail with its process still alive (no URL
# published, or the edge never routed). Leaving it running lets a retry collide
# on the ngrok web/API port and strands a dead PID in the service registry.
reap_failed_ngrok_tunnel() {
    [ -n "${NGROK_PID:-}" ] || return 0
    kill "$NGROK_PID" 2>/dev/null || true
    wait "$NGROK_PID" 2>/dev/null || true
    local kept_pids=() kept_names=() index=0
    for index in "${!PIDS[@]}"; do
        if [ "${PIDS[$index]}" != "$NGROK_PID" ]; then
            kept_pids+=("${PIDS[$index]}")
            kept_names+=("${NAMES[$index]}")
        fi
    done
    PIDS=("${kept_pids[@]}")
    NAMES=("${kept_names[@]}")
    NGROK_PID=""
}

start_ngrok_public_tunnel() {
    if ! command -v ngrok >/dev/null 2>&1; then
        echo "❌ ngrok is required for scripts/run.sh. Install it and configure an authtoken."
        exit 1
    fi
    if [ -z "${NGROK_AUTHTOKEN:-}" ]; then
        ngrok config check >/dev/null 2>&1 || {
            echo "❌ ngrok config is invalid or missing an authtoken. Run: ngrok config add-authtoken <token>"
            exit 1
        }
    fi

    WORKSPACE_DNS_LABEL="$(dns_label_from_workspace)"
    export NGROK_API_URL="http://127.0.0.1:$NGROK_WEB_PORT/api/tunnels"
    NGROK_DOMAIN_SUFFIX="${NGROK_DOMAIN_SUFFIX:-ngrok.app}"
    local configured_domain="${NGROK_WORKTREE_DOMAIN:-rose-${WORKSPACE_DNS_LABEL}.${NGROK_DOMAIN_SUFFIX}}"
    ngrok_configure_endpoint_mode 0 "$configured_domain"
    if [ "$NGROK_RESERVE_DOMAIN" = "1" ]; then
        WORKTREE_DOMAIN="$configured_domain"
        export WORKTREE_DOMAIN
        export PUBLIC_BASE_URL="https://$WORKTREE_DOMAIN"
        export VITE_ALLOWED_HOSTS="$WORKTREE_DOMAIN"
        export ALLOWED_ORIGINS="$ALLOWED_ORIGINS,$PUBLIC_BASE_URL"
        ensure_ngrok_domain_reserved
    fi

    mkdir -p "$RUN_CONTEXT_DIR"
    local ngrok_base_config="$HOME/Library/Application Support/ngrok/ngrok.yml"
    if [ ! -f "$ngrok_base_config" ]; then
        ngrok_base_config="$HOME/.config/ngrok/ngrok.yml"
    fi
    if [ ! -f "$ngrok_base_config" ] && [ -z "${NGROK_AUTHTOKEN:-}" ]; then
        ngrok_public_tunnel_fail "❌ Could not find the ngrok config file after ngrok config check succeeded." || return 1
    fi

    NGROK_CONFIG_FILE="$RUN_CONTEXT_DIR/ngrok-${WORKSPACE_DNS_LABEL}.yml"
    cat > "$NGROK_CONFIG_FILE" <<EOF
version: "3"
agent:
  web_addr: 127.0.0.1:$NGROK_WEB_PORT
EOF

    local -a ngrok_config_args=(--config "$NGROK_CONFIG_FILE")
    if [ -f "$ngrok_base_config" ]; then
        ngrok_config_args=(--config "$ngrok_base_config" --config "$NGROK_CONFIG_FILE")
    fi
    echo "🌐 Starting public frontend tunnel: $PUBLIC_BASE_URL → localhost:$FRONTEND_PORT"
    ngrok http "$FRONTEND_PORT" \
        "${ngrok_config_args[@]}" \
        "${NGROK_ENDPOINT_ARGS[@]}" \
        --log stdout \
        --log-format logfmt \
        --log-level info > "$RUN_CONTEXT_DIR/ngrok.log" 2>&1 &
    NGROK_PID=$!
    PUBLIC_TUNNEL_SERVICE_NAME="ngrok"
    PIDS+=($NGROK_PID); NAMES+=("$PUBLIC_TUNNEL_SERVICE_NAME")

    for attempt in $(seq 1 60); do
        if ! kill -0 "$NGROK_PID" 2>/dev/null; then
            echo "❌ ngrok exited before the public tunnel became ready."
            tail -60 "$RUN_CONTEXT_DIR/ngrok.log" || true
            echo ""
            echo "Required ngrok billing state: Pay-as-you-go plan (\$20/month + usage) with reserved domain $WORKTREE_DOMAIN."
            echo "Checkout: https://dashboard.ngrok.com/billing/choose-a-plan"
            ngrok_public_tunnel_fail "❌ ngrok exited before the public tunnel became ready." || return 1
        fi
        local tunnels_json="$RUN_CONTEXT_DIR/ngrok-tunnels.json"
        if curl -fsS "$NGROK_API_URL" > "$tunnels_json" 2>/dev/null; then
            if ngrok_publish_reported_environment "$tunnels_json" "$ALLOWED_ORIGINS"; then
                rm -f "$tunnels_json"
                echo "🌐 Public tunnel ready: $PUBLIC_BASE_URL"
                return 0
            fi
        fi
        sleep 1
    done

    echo "❌ ngrok tunnel did not become ready for ${PUBLIC_BASE_URL:-provider-assigned endpoint} → :$FRONTEND_PORT"
    echo "   ngrok API: $NGROK_API_URL"
    tail -80 "$RUN_CONTEXT_DIR/ngrok.log" || true
    ngrok_public_tunnel_fail "❌ ngrok tunnel never became ready." || return 1
}

start_public_tunnel() {
    case "$(public_tunnel_provider_for_mode "${BENCHMARK_EPHEMERAL_PUBLIC_TUNNEL:-0}")" in
        cloudflare)
            # A single best-effort provider is a single point of failure for the
            # whole benchmark stack. Fall back to ngrok rather than failing the
            # run when trycloudflare will not route.
            start_cloudflare_quick_tunnel && return 0
            start_ngrok_ephemeral_tunnel && return 0
            # Last resort: this worktree's already-reserved stable domain.
            #
            # Both providers above are ACCOUNT-GLOBAL and can be exhausted by
            # something this run does not own: trycloudflare rate-limits per IP
            # (429/1015), and ngrok's free ephemeral endpoint is a single shared
            # name, so a sibling Conductor worktree holding it fails this run
            # with ERR_NGROK_334. Neither is a defect in the code under test, and
            # killing a neighbor's stack to reclaim the slot is never this
            # script's call — so an isolated run would hard-fail /deploy's smoke
            # gate for a reason entirely outside the branch.
            #
            # The worktree domain is per-worktree, already reserved (no new
            # PAYG reservation), and contended only by a shared dev stack in
            # THIS worktree. If that stack holds it we still fail, exactly as
            # before, so this strictly widens the set of runs that can proceed.
            echo "⚠️  cloudflare and ephemeral ngrok are both unavailable; trying this worktree's reserved domain." >&2
            # An isolated run renames the workspace to "<worktree>-bench-<run id>",
            # which would derive a per-run domain that is NOT reserved. Binding it
            # fails, and reserving it would mint a billable PAYG domain per
            # benchmark run. Strip the run-scoped suffix so we reuse the domain the
            # worktree already owns, and hide NGROK_API_KEY so this path can only
            # ever BIND an existing reservation, never create one.
            if [ -z "${NGROK_WORKTREE_DOMAIN:-}" ]; then
                # Derive through the SAME helper the reservation was created
                # with, so character normalization and the 50-char truncation
                # match. Re-implementing it here drifts for long worktree names
                # and yields a hostname that was never reserved.
                local base_label
                base_label="$(CONDUCTOR_WORKSPACE_NAME="${CONDUCTOR_WORKSPACE_NAME%%-bench-*}" \
                    dns_label_from_workspace 2>/dev/null)" || base_label=""
                [ -n "$base_label" ] || base_label="$(basename "$(cd "$SCRIPT_DIR/.." && pwd)")"
                export NGROK_WORKTREE_DOMAIN="rose-${base_label}.${NGROK_DOMAIN_SUFFIX:-ngrok.app}"
                echo "   Reusing the worktree's reserved domain: $NGROK_WORKTREE_DOMAIN" >&2
            fi
            # Retire the failed ephemeral attempt first: it can still be running
            # and would contend with this one on the ngrok web/API port.
            reap_failed_ngrok_tunnel
            local saved_ngrok_api_key="${NGROK_API_KEY:-}"
            unset NGROK_API_KEY
            NGROK_PUBLIC_TUNNEL_NONFATAL=1
            if start_ngrok_public_tunnel; then
                NGROK_PUBLIC_TUNNEL_NONFATAL=0
                [ -n "$saved_ngrok_api_key" ] && export NGROK_API_KEY="$saved_ngrok_api_key"
                return 0
            fi
            NGROK_PUBLIC_TUNNEL_NONFATAL=0
            [ -n "$saved_ngrok_api_key" ] && export NGROK_API_KEY="$saved_ngrok_api_key"
            echo "❌ No public tunnel provider could serve :$FRONTEND_PORT (tried cloudflare, ephemeral ngrok, then the worktree domain)." >&2
            echo "   Set BENCHMARK_SKIP_PUBLIC_TUNNEL=1 for runs that do not need a public origin." >&2
            exit 1
            ;;
        ngrok) start_ngrok_public_tunnel ;;
        *) echo "❌ Invalid public tunnel mode." >&2; exit 2 ;;
    esac
}

write_services_manifest() {
    mkdir -p "$RUN_CONTEXT_DIR"
    local names_csv pids_csv
    names_csv="$(IFS=,; echo "${NAMES[*]:-}")"
    pids_csv="$(IFS=,; echo "${PIDS[*]:-}")"
    SERVICE_NAMES="$names_csv" SERVICE_PIDS="$pids_csv" SERVICE_STATUS="$SERVICE_STATUS" \
        BENCHMARK_MODE="$BENCHMARK_MODE" DB_CONTAINER="$DB_CONTAINER" \
        DB_VOLUME="$DB_VOLUME" DB_OWNED_BY_US="$DB_OWNED_BY_US" USE_SYSTEM_PG="$USE_SYSTEM_PG" \
        LOCAL_DB_NAME="$LOCAL_DB_NAME" LOCAL_DB_ACTUAL_PORT="$LOCAL_DB_ACTUAL_PORT" \
        WMH_MANIFEST_PORT="${WMH_MANIFEST_PORT:-0}" WMH_MANIFEST_URL="${WMH_MANIFEST_URL:-}" \
        WMH_MANIFEST_MODEL_NAME="${WMH_MANIFEST_MODEL_NAME:-}" \
        RUN_SH_PID="$$" RUN_CONTEXT_DIR="$RUN_CONTEXT_DIR" python3 - <<'PY'
import json
import os
from datetime import datetime, timezone


def env_int(name: str, default: int = 0) -> int:
    try:
        return int(os.environ.get(name, default))
    except (TypeError, ValueError):
        return default


names = [part for part in os.environ.get("SERVICE_NAMES", "").split(",") if part]
pids_raw = [part for part in os.environ.get("SERVICE_PIDS", "").split(",") if part]
services = []
for index, name in enumerate(names):
    pid = env_int("__missing__", 0)
    if index < len(pids_raw):
        try:
            pid = int(pids_raw[index])
        except ValueError:
            pid = 0
    services.append({"name": name, "pid": pid})

root = os.getcwd()
context_dir = os.environ.get("RUN_CONTEXT_DIR") or ".context"
data = {
    "schema_version": 1,
    "status": os.environ.get("SERVICE_STATUS", "unknown"),
    "generated_at": datetime.now(timezone.utc).isoformat(),
    "worktree": root,
    "run_sh_pid": env_int("RUN_SH_PID"),
    "benchmark_mode": os.environ.get("BENCHMARK_MODE", "false").lower() == "true",
    "ports": {
        "backend": env_int("BACKEND_PORT"),
        "frontend": env_int("FRONTEND_PORT"),
        "health": env_int("HEALTH_PORT"),
        "mac_app": env_int("MAC_APP_PORT"),
        "sdk_metrics": env_int("SDK_METRICS_PORT"),
        "local_db": env_int("LOCAL_DB_PORT"),
        # WMH port is only serving in benchmark/simulate context; 0 otherwise.
        "wmh": env_int("WMH_MANIFEST_PORT"),
        "ngrok_api": env_int("NGROK_WEB_PORT"),
    },
    "urls": {
        "backend": os.environ.get("BACKEND_URL", ""),
        "backend_api": os.environ.get("BACKEND_API_URL", ""),
        "frontend": f"http://localhost:{os.environ.get('FRONTEND_PORT', '')}",
        "public": os.environ.get("PUBLIC_BASE_URL", ""),
        "health": f"http://localhost:{os.environ.get('HEALTH_PORT', '')}",
        "sdk_metrics": f"http://localhost:{os.environ.get('SDK_METRICS_PORT', '')}",
        # Empty until the WMH server is confirmed serving (benchmark/simulate only).
        "wmh": os.environ.get("WMH_MANIFEST_URL", ""),
    },
    "temporal_task_queue": os.environ.get("TEMPORAL_TASK_QUEUE", ""),
    "wmh_model_name": os.environ.get("WMH_MANIFEST_MODEL_NAME", ""),
        "database": {
            "container": os.environ.get("DB_CONTAINER", ""),
            "volume": os.environ.get("DB_VOLUME", ""),
            "owned_by_run_sh": os.environ.get("DB_OWNED_BY_US", "false").lower() == "true",
            "use_system_postgres": os.environ.get("USE_SYSTEM_PG", "false").lower() == "true",
            "name": os.environ.get("LOCAL_DB_NAME", "victoria"),
            "port": env_int("LOCAL_DB_ACTUAL_PORT"),
            "runtime_port": 5432
            if os.environ.get("USE_SYSTEM_PG", "false").lower() == "true"
            else env_int("LOCAL_DB_PORT"),
        },
    "env": {
        "benchmark_anon_steel_profile": os.environ.get("BENCHMARK_ANON_STEEL_PROFILE", "").lower() in ("1", "true", "yes", "on"),
        "benchmark_disable_saved_browser_auth": os.environ.get("BENCHMARK_DISABLE_SAVED_BROWSER_AUTH", "").lower() in ("1", "true", "yes", "on"),
        "worker_processes": env_int("WORKER_PROCESSES", 8),
        "max_concurrent_workflows": env_int("MAX_CONCURRENT_WORKFLOWS", 50),
        "max_cached_workflows": env_int("MAX_CACHED_WORKFLOWS", 100),
        "max_concurrent_workflow_task_pollers": env_int("MAX_CONCURRENT_WORKFLOW_TASK_POLLERS", 8),
        "nonsticky_to_sticky_poll_ratio": float(os.environ.get("NONSTICKY_TO_STICKY_POLL_RATIO", "0.5")),
        "max_concurrent_activities": env_int("MAX_CONCURRENT_ACTIVITIES", 100),
        "max_concurrent_activity_task_pollers": env_int("MAX_CONCURRENT_ACTIVITY_TASK_POLLERS", 8),
    },
    "logs": {
        "backend": os.environ.get("BACKEND_LOG_FILE") or os.path.join(root, "back-end", "backend-logs.log"),
        "frontend": os.environ.get("FRONTEND_LOG_FILE") or os.path.join(root, "front-end", "frontend-logs.log"),
        "worker": os.environ.get("NAVI_WORKER_LOG_FILE") or os.path.join(root, "agents", "navi-worker-log.txt"),
    },
    "services": services,
}
tmp_path = os.path.join(root, context_dir, "services.json.tmp")
path = os.path.join(root, context_dir, "services.json")
with open(tmp_path, "w") as f:
    json.dump(data, f, indent=2, sort_keys=True)
    f.write("\n")
os.replace(tmp_path, path)
PY
    # Only publish a PUBLIC url when one actually exists. With
    # BENCHMARK_SKIP_PUBLIC_TUNNEL=1 the "public" URL is deliberately
    # http://localhost:<port>, which publish_url_manifest correctly rejects (it
    # requires a portless HTTPS origin). Without this guard the two flags
    # conflict and abort the whole stack with a misleading
    # "Failed to publish ephemeral public URL", even though the caller asked for
    # no tunnel at all.
    if [ "${BENCHMARK_EPHEMERAL_PUBLIC_TUNNEL:-0}" = "1" ] &&
        [ "${BENCHMARK_SKIP_PUBLIC_TUNNEL:-}" != "1" ]; then
        local services_manifest
        case "$RUN_CONTEXT_DIR" in
            /*) services_manifest="$RUN_CONTEXT_DIR/services.json" ;;
            *) services_manifest="$PWD/$RUN_CONTEXT_DIR/services.json" ;;
        esac
        public_tunnel_publish_url_manifest "$services_manifest" || {
            echo "❌ Failed to publish ephemeral public URL to $services_manifest" >&2
            return 1
        }
    fi
}

# ── World Model Harness (WMH) ──
# The WMH is a trace-grounded environment emulator used by simulate/shadow
# benchmarks. It runs as a standard run.sh-managed service on ALL non-prod runs
# (local + cloud). Two costs, gated differently:
#   - Serving (`wmh serve`, a loaded model idling on WMH_PORT): CHEAP → we serve
#     on every non-prod run whenever a built model artifact already exists.
#   - The first GEPA build from the R2 trace corpus: EXPENSIVE + needs R2 creds →
#     only attempted when this is a benchmark run (BENCHMARK_MODE) or an explicit
#     opt-in (SERVE_WORLD_MODEL=1). Building is NEVER fatal: a failed/absent build
#     just means no WMH this run (simulate benchmarks will error clearly; smoke
#     and plain dev runs are unaffected).
# Hard guard: NEVER in prod (ENVIRONMENT=production; prod agents run on Fly via
# worker.py and never invoke run.sh, but the guard makes the invariant explicit).
WMH_PID=""
WMH_MODEL_NAME="${WMH_MODEL_NAME:-rose-archive}"

should_serve_world_model() {
    # Serve on every non-prod run; only prod is excluded.
    [ "${ENVIRONMENT:-}" = "production" ] && return 1
    # Explicit opt-out: the cloud-bench box uses this for real-mode (non-simulate)
    # runs where no WMH is needed, so the (slow, R2-corpus + GEPA) cold build never
    # blocks status=running. Simulate runs leave this unset and still build/serve.
    [ "${BENCHMARK_SKIP_WMH_BUILD:-}" = "1" ] && return 1
    return 0
}

start_world_model_harness() {
    should_serve_world_model || return 0

    mkdir -p "$RUN_CONTEXT_DIR"
    local wmh_log
    case "$RUN_CONTEXT_DIR" in
        /*) wmh_log="$RUN_CONTEXT_DIR/wmh-serve-log.txt" ;;
        *)  wmh_log="$PWD/$RUN_CONTEXT_DIR/wmh-serve-log.txt" ;;
    esac

    # Shared, persistent build root so the model is built ONCE and reused across
    # every run — NOT the per-run context dir (that would rebuild each time).
    # Mirrors _DEFAULT_WMH_BUILD_ROOT in agents/benchmarks/world_model_harness.py.
    local build_dir="${WMH_BUILD_DIR:-$PWD/.context/world-model}"
    case "$build_dir" in
        /*) : ;;                       # already absolute
        *)  build_dir="$PWD/$build_dir" ;;
    esac

    local model_ready=false
    if [ -f "$build_dir/build.manifest.json" ] && [ -d "$build_dir/models/$WMH_MODEL_NAME" ]; then
        model_ready=true
    fi

    _wmh_build() {
        (cd agents && source venv/bin/activate && \
            WMH_BUILD_DIR="$build_dir" WMH_MODEL_NAME="$WMH_MODEL_NAME" \
            python -c "from benchmarks.world_model_harness import update_world_model_for_simulation as u; u(progress=lambda e: print('[WMH]', e.get('title'), e.get('status'), flush=True))" \
            >>"$wmh_log" 2>&1)
    }

    if ! $model_ready; then
        # First build (GEPA) is expensive + needs the R2 corpus — only when this
        # run is allowed to build. Non-fatal: on failure we warn and skip serving.
        if $BENCHMARK_MODE || [ "${SERVE_WORLD_MODEL:-}" = "1" ]; then
            echo "🌍 Building World Model Harness corpus ($WMH_MODEL_NAME) from trace archive → $build_dir (first build)"
            if _wmh_build; then
                model_ready=true
            else
                echo "⚠️  World Model Harness build failed — WMH not served this run (see $wmh_log). Simulate benchmarks will error until it builds; smoke/dev runs are unaffected."
                tail -20 "$wmh_log" || true
            fi
        else
            echo "ℹ️  No prebuilt World Model at $build_dir — skipping WMH serve. Build it via a benchmark run or SERVE_WORLD_MODEL=1."
        fi
    elif $BENCHMARK_MODE && [ "${BENCHMARK_SKIP_WMH_DELTA:-}" != "1" ]; then
        # Cheap delta refresh so benchmark runs pick up new traces; never fatal.
        # BENCHMARK_SKIP_WMH_DELTA=1 serves the pre-built model verbatim with NO
        # archive read/refresh — the fast per-run path for the persistent cloud-bench
        # box, where the model is (re)built ONLY via an explicit --refresh-wmh step
        # and every per-run start must SERVE the cached artifact, never touch R2.
        _wmh_build || echo "⚠️  WMH delta refresh failed — serving existing model (see $wmh_log)."
    elif $BENCHMARK_MODE; then
        echo "🌍 BENCHMARK_SKIP_WMH_DELTA=1 — serving pre-built World Model verbatim (no delta refresh)"
    fi

    $model_ready || return 0

    echo "🌍 Starting World Model Harness: serve $WMH_MODEL_NAME on port $WMH_PORT (root $build_dir)"
    # Serve via serve_world_model.py (Rose inference provider: compute tokens +
    # claudeAuth + rotation) instead of `wmh serve` (raw direct-Anthropic key).
    (cd agents && source venv/bin/activate && \
        exec python -m benchmarks.serve_world_model --name "$WMH_MODEL_NAME" --port "$WMH_PORT" --root "$build_dir") \
        >>"$wmh_log" 2>&1 &
    WMH_PID=$!
    PIDS+=($WMH_PID); NAMES+=("wmh")

    # Cold model loading on a freshly restored cloud volume can legitimately take
    # longer than 30 seconds before Uvicorn binds. Keep waiting while the owned
    # process is alive, with a bounded budget aligned to WMH inference startup.
    local health_timeout_default=180
    local health_timeout_max=600
    local health_timeout="${WMH_HEALTH_TIMEOUT_SECONDS:-$health_timeout_default}"
    local health_timeout_max_digits=${#health_timeout_max}
    if ! [[ "$health_timeout" =~ ^[1-9][0-9]*$ ]] || \
        (( ${#health_timeout} > health_timeout_max_digits )) || \
        (( health_timeout > health_timeout_max )); then
        echo "⚠️  Invalid WMH_HEALTH_TIMEOUT_SECONDS=$health_timeout; using 180s."
        health_timeout=$health_timeout_default
    fi
    local ready=false
    local health_attempt=0
    local health_deadline=$((SECONDS + health_timeout))
    while (( health_attempt < health_timeout && SECONDS <= health_deadline )); do
        health_attempt=$((health_attempt + 1))
        if ! kill -0 "$WMH_PID" 2>/dev/null; then
            echo "⚠️  WMH server exited before becoming ready — not served this run (see $wmh_log)."
            tail -20 "$wmh_log" || true
            return 0
        fi
        if curl -fsS --connect-timeout 1 --max-time 1 \
            "http://localhost:$WMH_PORT/healthz" >/dev/null 2>&1; then
            ready=true
            break
        fi
        if (( health_attempt < health_timeout && SECONDS < health_deadline )); then
            sleep 1
        fi
    done
    if ! $ready; then
        echo "⚠️  WMH server did not answer /healthz on port $WMH_PORT within ${health_timeout}s — not served this run (see $wmh_log)."
        tail -20 "$wmh_log" || true
        return 0
    fi

    # Only now publish WMH to the manifest and benchmark env — the server is confirmed up.
    export WMH_MANIFEST_PORT="$WMH_PORT"
    export WMH_MANIFEST_URL="http://localhost:$WMH_PORT"
    export WMH_MANIFEST_MODEL_NAME="$WMH_MODEL_NAME"
    export WMH_BASE_URL="http://localhost:$WMH_PORT"
    export WMH_MODEL_NAME
    echo "🌍 World Model Harness ready: $WMH_BASE_URL (model $WMH_MODEL_NAME)"
}

kill_tree() {
    local pid=$1
    for child in $(pgrep -P "$pid" 2>/dev/null); do
        kill_tree "$child"
    done
    kill "$pid" 2>/dev/null || true
}

# SIGTERM the tree, wait briefly, then SIGKILL any survivors
kill_tree_hard() {
    local pid=$1
    kill_tree "$pid"
    sleep 1
    # Kill any survivors that ignored SIGTERM
    for child in $(pgrep -P "$pid" 2>/dev/null); do
        kill -9 "$child" 2>/dev/null || true
    done
    kill -9 "$pid" 2>/dev/null || true
}

cleanup() {
    if $SHUTTING_DOWN; then return; fi
    SHUTTING_DOWN=true
    echo "🛑 Stopping all services... (triggered by: $(caller 0 2>/dev/null || echo 'EXIT trap'), DB_OWNED_BY_US=$DB_OWNED_BY_US)"
    # Kill only the process trees we spawned (SIGTERM then SIGKILL)
    for pid in "${PIDS[@]}"; do
        if [ -n "${BACKEND_PID:-}" ] && [ "$pid" = "$BACKEND_PID" ] \
            && [ -n "${BACKEND_PGID:-}" ]; then
            terminate_backend_group || true
        else
            kill_tree_hard "$pid"
        fi
    done
    # Sweep by manifest, cwd, and service ports in case a wrapper exited before
    # its child, or a descendant reparented during a cascade shutdown. Isolated
    # benchmark runs skip the broad same-worktree sweep because their process
    # group and explicit PIDS list are the isolation boundary.
    if [ "$BENCHMARK_ISOLATED_RUN" != "true" ]; then
        bash "$SCRIPT_DIR/kill-services.sh" || true
    fi
    if $DB_OWNED_BY_US && ! $USE_SYSTEM_PG; then
        run_cleanup_owned_db_container \
            "$DB_OWNED_CONTAINER_ID" "$DB_CONTAINER" "$DB_VOLUME" "$BENCHMARK_ISOLATED_RUN"
    fi
    if $USE_SYSTEM_PG && $SYSTEM_DB_OWNED_BY_US; then
        PGPASSWORD=postgres dropdb -h localhost -U postgres --if-exists "$LOCAL_DB_NAME" >/dev/null 2>&1 || true
    fi
    SERVICE_STATUS=stopped
    write_services_manifest || true
    [ -n "$NGROK_CONFIG_FILE" ] && rm -f "$NGROK_CONFIG_FILE"
    [ -n "$FAIL_DIR" ] && rm -rf "$FAIL_DIR"
    wait 2>/dev/null
}
trap 'release_seed_lock_if_held; cleanup' EXIT

# Wrapper: run a service and write its exit code to a temp file on failure
FAIL_DIR=$(mktemp -d)
run_service() {
    local name="$1"
    shift
    "$@"
    local code=$?
    if [ $code -ne 0 ]; then
        echo "$name" > "$FAIL_DIR/failed"
        echo "$code" > "$FAIL_DIR/exit_code"
    fi
    return $code
}

# Public URL flow:
#   CONDUCTOR_WORKSPACE_NAME -> rose-<workspace>.<suffix>
#   stable local ngrok or run-scoped cloud tunnel -> Vite on FRONTEND_PORT
#   backend exposes PUBLIC_BASE_URL for /api/test-payment/public-url
#
# BENCHMARK_SKIP_PUBLIC_TUNNEL=1 opt-out: a self-contained cloud-bench box
# (scripts/run-bench-cloud) runs simulate-only, where the WMH intercepts every
# provider/environment boundary and no external browser ever needs to reach the
# frontend over the internet. Standing up a public tunnel per one-shot
# Fly machine is fragile and unnecessary there, so we point PUBLIC_BASE_URL at the
# local frontend and skip the tunnel + tunnel smoke. Never set this for the normal
# dev/benchmark stack — real browser agents need the public URL.
if [ "${BENCHMARK_SKIP_PUBLIC_TUNNEL:-}" = "1" ]; then
    export PUBLIC_BASE_URL="http://localhost:$FRONTEND_PORT"
    export VITE_ALLOWED_HOSTS="localhost"
    export ALLOWED_ORIGINS="$ALLOWED_ORIGINS,$PUBLIC_BASE_URL"
    echo "🌐 BENCHMARK_SKIP_PUBLIC_TUNNEL=1 — skipping public tunnel; PUBLIC_BASE_URL=$PUBLIC_BASE_URL (simulate-only cloud bench)"
else
    start_public_tunnel
fi
# Fast-mode proxy routes sandbox code-agent (claude-code / codex) LLM calls
# through the local proxy for cache capture. Locally this pins those calls to a
# priority tier that can have 0 credits (e.g. Opus 4.8), which fails the
# claude-code-agent smoke with an auth/credit error unrelated to E2B or tokens.
# DISABLE_FAST_MODE_PROXY=1 empties both URLs so the sandbox falls back to the
# direct claudeAuth path (codeAgentFastModeEnv treats "" as "no proxy"). This is
# a local-only convenience — prod code agents never route through this proxy.
if [ "${DISABLE_FAST_MODE_PROXY:-}" = "1" ]; then
    export FAST_MODE_ANTHROPIC_PROXY_URL=""
    export FAST_MODE_CODEX_PROXY_URL=""
    echo "⚡ DISABLE_FAST_MODE_PROXY=1 — fast-mode proxy off; sandbox code agents use the direct claudeAuth path"
else
    export FAST_MODE_ANTHROPIC_PROXY_URL="$PUBLIC_BASE_URL/anthropic-proxy"
    export FAST_MODE_CODEX_PROXY_URL="$PUBLIC_BASE_URL/codex-proxy"
fi
export BACKEND_LOG_FILE="${BACKEND_LOG_FILE:-$PWD/back-end/backend-logs.log}"
export FRONTEND_LOG_FILE="${FRONTEND_LOG_FILE:-$PWD/front-end/frontend-logs.log}"
export NAVI_WORKER_LOG_FILE="${NAVI_WORKER_LOG_FILE:-$PWD/agents/navi-worker-log.txt}"

export BACKEND_LOG_FILE="${BACKEND_LOG_FILE:-$PWD/back-end/backend-logs.log}"
export FRONTEND_LOG_FILE="${FRONTEND_LOG_FILE:-$PWD/front-end/frontend-logs.log}"
export NAVI_WORKER_LOG_FILE="${NAVI_WORKER_LOG_FILE:-$PWD/agents/navi-worker-log.txt}"

if [ "$BENCHMARK_ISOLATED_RUN" = "true" ]; then
    case "$RUN_CONTEXT_DIR" in
        /*) BENCHMARK_LOG_DIR="$RUN_CONTEXT_DIR/logs" ;;
        *) BENCHMARK_LOG_DIR="$PWD/$RUN_CONTEXT_DIR/logs" ;;
    esac
    mkdir -p "$BENCHMARK_LOG_DIR"
    export BACKEND_LOG_FILE="$BENCHMARK_LOG_DIR/backend.log"
    export FRONTEND_LOG_FILE="$BENCHMARK_LOG_DIR/frontend.log"
    export NAVI_WORKER_LOG_FILE="$BENCHMARK_LOG_DIR/worker.log"
    export NAVI_WORKER_LOG_STREAM=false
fi

# Every concurrent benchmark stack owns its production frontend bundle. Vite
# empties its output directory while building, so sharing front-end/dist lets an
# isolated smoke/payment build delete chunks that the semantic preview is
# actively serving.
FRONTEND_DIST_DIR=$(resolve_frontend_dist_dir \
    "$PWD" "$BENCHMARK_ISOLATED_RUN" "${BENCHMARK_RUN_ID:-}" "$FRONTEND_PORT")
export FRONTEND_DIST_DIR
mkdir -p "$(dirname "$FRONTEND_DIST_DIR")"

# A few fleet-width cold starts have left `tsx src/server.ts` alive but stuck
# during module loading (backend log contains only the first Supabase warning).
# The public-tunnel smoke used to discover that indirectly after 60 blank curls
# and abort the slot. Own backend startup here: one clean process-tree restart
# is allowed before the normal stack-level readiness owner decides the box is
# unhealthy. This is startup supervision, not a benchmark/task retry.
BACKEND_INDEX=${#PIDS[@]}
PIDS+=("")
NAMES+=("back-end")
BACKEND_PID=""
BACKEND_PGID=""
launch_backend_service() {
    if $BENCHMARK_MODE; then
        if [ "$BENCHMARK_ISOLATED_RUN" = "true" ]; then
            # Give the backend its own process group. A hung import can leave a
            # TERM-ignoring descendant; group ownership lets restart/cleanup
            # prove every descendant is gone before a replacement can bind.
            FAIL_DIR="$FAIL_DIR" BACKEND_LOG_FILE="$BACKEND_LOG_FILE" BACKEND_PORT="$BACKEND_PORT" \
                python3 "$SCRIPT_DIR/run-in-new-session.py" bash -c '
                    set +e
                    cd back-end || exit 1
                    rm -f "$BACKEND_LOG_FILE"
                    PORT="$BACKEND_PORT" npx tsx src/bootstrap.ts > "$BACKEND_LOG_FILE" 2>&1
                    code=$?
                    if [ "$code" -ne 0 ]; then
                        printf "%s\n" back-end > "$FAIL_DIR/failed"
                        printf "%s\n" "$code" > "$FAIL_DIR/exit_code"
                    fi
                    exit "$code"
                ' &
            BACKEND_PID=$!
            BACKEND_PGID="$BACKEND_PID"
        else
            run_service "back-end" bash -c 'set -eo pipefail; cd back-end && rm -f "$BACKEND_LOG_FILE" && PORT=$BACKEND_PORT npx tsx src/bootstrap.ts 2>&1 | tee "$BACKEND_LOG_FILE"' &
            BACKEND_PID=$!
            BACKEND_PGID=""
        fi
    else
        run_service "back-end" bash -c 'set -eo pipefail; cd back-end && rm -f "$BACKEND_LOG_FILE" && PORT=$BACKEND_PORT npx tsx watch src/bootstrap.ts 2>&1 | tee "$BACKEND_LOG_FILE"' &
        BACKEND_PID=$!
        BACKEND_PGID=""
    fi
    PIDS[$BACKEND_INDEX]="$BACKEND_PID"
}
terminate_backend_group() {
    local pgid="${BACKEND_PGID:-}" root="${BACKEND_PID:-}" still_alive=0
    [ -n "$pgid" ] || { [ -z "$root" ] || kill_tree_hard "$root"; return; }
    kill -TERM -- "-$pgid" 2>/dev/null || true
    for _ in 1 2 3 4 5; do
        if ! kill -0 -- "-$pgid" 2>/dev/null; then still_alive=0; break; fi
        still_alive=1
        sleep 1
    done
    [ "$still_alive" = 0 ] || kill -KILL -- "-$pgid" 2>/dev/null || true
    for _ in 1 2 3 4 5; do
        kill -0 -- "-$pgid" 2>/dev/null || { still_alive=0; break; }
        still_alive=1
        sleep 0.2
    done
    wait "$root" 2>/dev/null || true
    if [ "$still_alive" != 0 ] || kill -0 -- "-$pgid" 2>/dev/null; then
        echo "❌ backend process group $pgid survived termination" >&2
        return 1
    fi
    BACKEND_PID=""
    BACKEND_PGID=""
}
restart_backend_service() {
    echo "♻️  restarting hung backend process tree (pid=$BACKEND_PID)"
    terminate_backend_group || return 1
    rm -f "$FAIL_DIR/failed" "$FAIL_DIR/exit_code"
    launch_backend_service
}
isolated_backend_ready_attempts() {
    # The long budget applies to ANY box that just materialised the full prod DB —
    # a cold seed (FIRST_RUN_SEEDED) OR a cache/dump restore (DB_RESTORED). Both
    # leave the backend the same large state to warm; capping restore at 60s timed
    # out every warm box and starved the barrier. See backend_ready_budget().
    local _frs=0 _dbr=0
    $FIRST_RUN_SEEDED && _frs=1
    $DB_RESTORED && _dbr=1
    backend_ready_budget "$_frs" "$_dbr" "${CLOUDBENCH_BACKEND_START_READY_ATTEMPTS:-}"
}
wait_for_isolated_backend_ready() {
    local launch_attempt probe_attempt
    local attempts
    attempts="$(isolated_backend_ready_attempts)"
    for launch_attempt in 1 2; do
        for probe_attempt in $(seq 1 "$attempts"); do
            if curl -fsS "http://localhost:$BACKEND_PORT/health" >/dev/null 2>&1; then
                [ "$launch_attempt" = 1 ] \
                    && echo "✅ isolated backend healthy on first launch" \
                    || echo "✅ backend became healthy after restart"
                return 0
            fi
            kill -0 "$BACKEND_PID" 2>/dev/null || break
            sleep 1
        done
        echo "⚠️  backend startup attempt $launch_attempt/2 did not become healthy" >&2
        tail -40 "$BACKEND_LOG_FILE" 2>/dev/null | sed 's/^/   | /' >&2 || true
        [ "$launch_attempt" = 1 ] || return 1
        restart_backend_service
    done
    return 1
}

# Launch each service
if $BENCHMARK_MODE; then
    export TRACE_ARCHIVE_ENABLED="${TRACE_ARCHIVE_ENABLED:-1}"
    # Do not manufacture a shell-level `local` backend here. Both the backend
    # and Python worker load their injected .env files, where cloud benchmarks
    # are configured for R2; an exported fallback wins over dotenv and strands
    # the only gold trace on the disposable fleet volume. An explicitly
    # exported caller value is already inherited, and no-env local development
    # still uses each provider's built-in local default.
    export TRACE_ARCHIVE_LOCAL_DIR="${TRACE_ARCHIVE_LOCAL_DIR:-$PWD/.context}"
    export BLACKBOX_TEST_CAPTURE_OUTBOUND="${BLACKBOX_TEST_CAPTURE_OUTBOUND:-1}"
    export BLACKBOX_TEST_REPLAY_OUTBOUND="${BLACKBOX_TEST_REPLAY_OUTBOUND:-0}"
    export BLACKBOX_TEST_FAKE_SURGE="${BLACKBOX_TEST_FAKE_SURGE:-1}"
    # Capture-outbound flips IS_BLACKBOX_TEST, which would disable the dev-phone
    # OTP login bypass — but the message-person iMessage relay needs it to
    # auto-login the benchmark user. Re-enable the login bypass here (still
    # IS_DEV-gated, so prod is unaffected) while outbound SMS capture stays on.
    export BENCHMARK_ALLOW_DEV_OTP_LOGIN="${BENCHMARK_ALLOW_DEV_OTP_LOGIN:-1}"
    export SURGE_API_KEY="${SURGE_API_KEY:-blackbox-surge-key}"
    export SURGE_ACCOUNT_ID="${SURGE_ACCOUNT_ID:-blackbox-surge-account}"
    export VITE_DEV_AUTO_LOGIN_PHONE="${VITE_DEV_AUTO_LOGIN_PHONE:-+15555550123}"
    export VITE_DEV_AUTO_LOGIN_OTP="${VITE_DEV_AUTO_LOGIN_OTP:-191919}"

fi

# Build the benchmark frontend before launching the backend and worker. Building
# alongside eight worker processes can starve Vite long enough for the public
# tunnel readiness check to fail even though the application is healthy.
if $BENCHMARK_MODE && [ "${BENCHMARK_BUNDLED_FRONTEND:-false}" = "true" ]; then
    echo "📦 Building bundled frontend before starting runtime services..."
    FRONTEND_BUILD_NODE_OPTIONS="${NODE_OPTIONS:-}"
    case " $FRONTEND_BUILD_NODE_OPTIONS " in
        *" --max-old-space-size="*) ;;
        *)
            FRONTEND_BUILD_NODE_OPTIONS="${FRONTEND_BUILD_NODE_OPTIONS:+$FRONTEND_BUILD_NODE_OPTIONS }--max-old-space-size=${BENCHMARK_FRONTEND_BUILD_OLD_SPACE_MB:-3584}"
            ;;
    esac
    (cd front-end && rm -f "$FRONTEND_LOG_FILE" && \
        NODE_OPTIONS="$FRONTEND_BUILD_NODE_OPTIONS" VITE_BACKEND_API_URL="$PUBLIC_BASE_URL" \
        VITE_ENABLE_REACT_GRAB=false VITE_REALTIME_PRIVATE=false \
        npx vite build --outDir "$FRONTEND_DIST_DIR" --emptyOutDir > "$FRONTEND_LOG_FILE" 2>&1)
fi
launch_backend_service

# Front-end is always launched. Public payment benchmarks use a production bundle
# so the cloud browser does not fetch the Vite development module graph over ngrok.
if $BENCHMARK_MODE && [ "${BENCHMARK_BUNDLED_FRONTEND:-false}" = "true" ]; then
    run_service "front-end" bash -c 'set -eo pipefail; cd front-end && npx vite preview --outDir "$FRONTEND_DIST_DIR" --host 0.0.0.0 --port $FRONTEND_PORT --strictPort >> "$FRONTEND_LOG_FILE" 2>&1' &
elif [ "$BENCHMARK_ISOLATED_RUN" = "true" ]; then
    run_service "front-end" bash -c 'set -eo pipefail; cd front-end && rm -f "$FRONTEND_LOG_FILE" && VITE_DEV_PORT=$FRONTEND_PORT npx vite > "$FRONTEND_LOG_FILE" 2>&1' &
else
    run_service "front-end" bash -c 'set -eo pipefail; cd front-end && rm -f "$FRONTEND_LOG_FILE" && VITE_DEV_PORT=$FRONTEND_PORT npx vite 2>&1 | tee "$FRONTEND_LOG_FILE"' &
fi
FRONTEND_PID=$!
PIDS+=("$FRONTEND_PID"); NAMES+=("front-end")

# mac-app is skipped in benchmark mode (Electron is heavy and smoke doesn't touch it).
if ! $BENCHMARK_MODE && $IS_MAC; then
    run_service "mac-app" bash -c 'set -eo pipefail; cd mac-app && source ~/.nvm/nvm.sh && nvm use 20.10.0 && rm -f mac-app-console-logs.log mac-app-ipc-logs.log && VITE_BACKEND_API_URL=http://localhost:$BACKEND_PORT npm run dev 2>&1 | tee mac-app-console-logs.log' &
    PIDS+=($!); NAMES+=("mac-app")
fi

if $BENCHMARK_MODE; then
    run_service "agents" bash -c 'set -eo pipefail; cd agents && source venv/bin/activate && ENABLE_BENCHMARK_MEMORY_BASELINE=1 HEALTH_CHECK_PORT=$HEALTH_PORT SDK_METRICS_PORT=$SDK_METRICS_PORT ./scripts/run_local_worker.sh' &
else
    run_service "agents" bash -c 'set -eo pipefail; cd agents && source venv/bin/activate && HEALTH_CHECK_PORT=$HEALTH_PORT SDK_METRICS_PORT=$SDK_METRICS_PORT ./scripts/run_local_worker.sh' &
fi
PIDS+=($!); NAMES+=("agents")

# Benchmark Hub poller: claims runs dispatched from the in-app Benchmarks tab
# and executes them on this machine. Without it a dispatched run sits queued
# forever — the hub's basic flow MUST work on a plain dev stack. Skipped in
# benchmark mode (the isolated bench stack must never claim hub dispatches).
if ! $BENCHMARK_MODE; then
    run_service "hub-poller" bash -c 'set -eo pipefail; rm -f hub-poller-logs.log && HUB_URL=http://localhost:$BACKEND_PORT scripts/run-bench-hub-poller --local 2>&1 | tee hub-poller-logs.log' &
    PIDS+=($!); NAMES+=("hub-poller")
fi

# World Model Harness (benchmark/simulate only — never prod). Builds from the
# trace corpus and serves on WMH_PORT; sets WMH_BASE_URL/WMH_MODEL_NAME + manifest
# fields when it comes up. A no-op on plain (non-benchmark) run.sh.
start_world_model_harness

if [ "$BENCHMARK_ISOLATED_RUN" = "true" ]; then
    wait_for_isolated_backend_ready || {
        echo "❌ isolated backend failed both supervised startup attempts" >&2
        exit 1
    }
fi

wait_for_frontend_ready "$FRONTEND_PID" "$FRONTEND_PORT" "$FRONTEND_LOG_FILE" || exit 1

if [ "${BENCHMARK_SKIP_PUBLIC_TUNNEL:-}" = "1" ]; then
    echo "⏭️  BENCHMARK_SKIP_PUBLIC_TUNNEL=1 — skipping public tunnel smoke (simulate-only cloud bench)"
else
    echo "⏳ Verifying public tunnel smoke..."
    bash scripts/test-public-tunnel.sh
fi

# Readiness consumers must not start benchmark work until the public endpoint
# has passed its smoke check. Publishing running earlier leaves a race where
# run.sh can fail the tunnel immediately after the harness accepts the stack.
SERVICE_STATUS=running
write_services_manifest
echo "🧭 Service manifest: $RUN_CONTEXT_DIR/services.json"
echo "🌐 Public frontend: $PUBLIC_BASE_URL"

# ── Post-launch: verify exactly one listener per service port ──
# Wait for services to bind, then confirm no duplicate listeners.
# Only the backend port is checked (the critical one for API calls); the
# agents worker binds to SDK_METRICS_PORT which may race with health.
if $IS_CLOUD; then
    echo -n "⏳ Verifying port bindings..."
    VERIFY_RETRIES=15
    for attempt in $(seq 1 $VERIFY_RETRIES); do
        sleep 2
        BACKEND_READY=false
        if python3 -c "import socket; s=socket.socket(); s.settimeout(1); exit(0 if s.connect_ex(('127.0.0.1',$BACKEND_PORT))==0 else 1); s.close()" 2>/dev/null; then
            BACKEND_READY=true
        fi
        WORKER_READY=false
        if python3 -c "import socket; s=socket.socket(); s.settimeout(1); exit(0 if s.connect_ex(('127.0.0.1',$SDK_METRICS_PORT))==0 else 1); s.close()" 2>/dev/null; then
            WORKER_READY=true
        fi
        if $BACKEND_READY && $WORKER_READY; then
            echo " backend=$BACKEND_PORT ✓  worker=$SDK_METRICS_PORT ✓"
            break
        fi
        if [ "$attempt" -eq "$VERIFY_RETRIES" ]; then
            echo ""
            $BACKEND_READY || echo "   ❌ Backend not listening on $BACKEND_PORT"
            $WORKER_READY  || echo "   ❌ Worker not listening on $SDK_METRICS_PORT"
            echo "   Continuing anyway — services may still be starting"
        fi
    done
fi

# Poll for failed children every second
while true; do
    if $SHUTTING_DOWN; then break; fi

    # Check if any process has died
    for i in "${!PIDS[@]}"; do
        pid="${PIDS[$i]}"
        if ! kill -0 "$pid" 2>/dev/null; then
            # Process is gone — get its exit code
            # `run.sh` uses `set -e`; a bare non-zero `wait` would trigger the
            # EXIT trap before we can identify the failed service and code.
            if wait "$pid" 2>/dev/null; then
                code=0
            else
                code=$?
            fi
            name="${NAMES[$i]}"
            if [ "$name" = "ngrok" ] && \
                ! public_tunnel_process_is_required "$name" "${BENCHMARK_EPHEMERAL_PUBLIC_TUNNEL:-0}"; then
                echo "⚠️  local public tunnel $name (PID $pid) exited with code $code; keeping local services running."
                unset "PIDS[$i]"
                unset "NAMES[$i]"
                write_services_manifest || true
                continue
            fi
            code="$(run_required_service_exit_code "$code")"
            echo ""
            echo "❌ $name (PID $pid) exited with code $code — shutting down all services."
            # Log which services are still alive for traceability
            for j in "${!PIDS[@]}"; do
                other_pid="${PIDS[$j]}"
                other_name="${NAMES[$j]}"
                if [ "$j" != "$i" ] && [ -n "$other_pid" ]; then
                    if kill -0 "$other_pid" 2>/dev/null; then
                        echo "   ├── $other_name (PID $other_pid): still running — will be killed"
                    else
                        wait "$other_pid" 2>/dev/null; other_code=$?
                        echo "   ├── $other_name (PID $other_pid): already dead (code $other_code)"
                    fi
                fi
            done
            cleanup
            rm -rf "$FAIL_DIR"
            exit "$code"
        fi
    done

    # If all children are gone, exit
    remaining=0
    for pid in "${PIDS[@]}"; do
        if [ -n "$pid" ]; then remaining=1; break; fi
    done
    if [ $remaining -eq 0 ]; then
        echo "⚠️  All services exited (code 0) — nothing left to monitor. Shutting down."
        break
    fi

    sleep 1
done

rm -rf "$FAIL_DIR"
